                                                                                                                                                                                                                                                                                                          pg_get_functiondef                                                                                                                                                                                                                                                                                                          
--------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
 CREATE OR REPLACE FUNCTION public.add_status_if_missing(tbl_name text)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
  RETURNS void                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
  LANGUAGE plpgsql                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
 AS $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
 begin                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +
   if not exists (                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
       select 1 from information_schema.columns                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
           where table_name = tbl_name                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +
               and column_name = 'status'                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
                 ) then                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
                     execute format('alter table %I add column status text default ''pending'';', tbl_name);                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
                       end if;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
                       end $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
 
 CREATE OR REPLACE FUNCTION public.advance_legitimacy(new_stage text)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
  RETURNS void                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
  LANGUAGE plpgsql                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
  SECURITY DEFINER                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
 AS $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
 declare                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
   uid uuid := auth.uid();                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
     new_progress int;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +
     begin                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
       if new_stage = 'initiated' then                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +
           new_progress := 25;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
             elsif new_stage = 'verified' then                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
                 new_progress := 50;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +
                   elsif new_stage = 'sanctified' then                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +
                       new_progress := 75;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
                         elsif new_stage = 'commissioned' then                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
                             new_progress := 100;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
                               else                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
                                   raise exception 'Invalid legitimacy stage: %', new_stage;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
                                     end if;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                       update legitimacy                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
                                         set progress = new_progress,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
                                               stage = new_stage,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
                                                     updated_at = now()                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
                                                       where user_id = uid;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
                                                       end;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
                                                       $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
 
 CREATE OR REPLACE FUNCTION public.advance_workflow(p_workflow_id uuid, p_to_state text, p_note text)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
  RETURNS boolean                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
  LANGUAGE plpgsql                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
  SECURITY DEFINER                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
 AS $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
                                                                                                                       DECLARE                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
                                                                                                                         me uuid := ats_current_member_id();                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
                                                                                                                           wf ats_workflows;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
                                                                                                                             tr ats_workflow_transitions;                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
                                                                                                                             BEGIN                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
                                                                                                                               SELECT * INTO wf                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
                                                                                                                                 FROM ats_workflows                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
                                                                                                                                   WHERE id = p_workflow_id;                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                                                                                     IF wf.id IS NULL THEN                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
                                                                                                                                         RAISE EXCEPTION 'Workflow not found';                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
                                                                                                                                           END IF;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                                                                                             SELECT * INTO tr                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
                                                                                                                                               FROM ats_workflow_transitions                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
                                                                                                                                                 WHERE from_state = wf.state                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
                                                                                                                                                     AND to_state = p_to_state;                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                                                                                                       IF tr.id IS NULL THEN                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
                                                                                                                                                           RAISE EXCEPTION 'Invalid transition from % to %', wf.state, p_to_state;                                                                                                                                                                                                                                                                                                                                                                                                   +
                                                                                                                                                             END IF;                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                                                                                                               -- Authority checks                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
                                                                                                                                                                 IF tr.requires_approve THEN                                                                                                                                                                                                                                                                                                                                                                                                                                         +
                                                                                                                                                                     IF NOT ats_has_workflow_authority(wf.ministry_id, wf.sector_id, 'approve') THEN                                                                                                                                                                                                                                                                                                                                                                                 +
                                                                                                                                                                           RAISE EXCEPTION 'Approval authority required';                                                                                                                                                                                                                                                                                                                                                                                                            +
                                                                                                                                                                               END IF;                                                                                                                                                                                                                                                                                                                                                                                                                                               +
                                                                                                                                                                                 END IF;                                                                                                                                                                                                                                                                                                                                                                                                                                             +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                                                                                                                                   IF tr.requires_override THEN                                                                                                                                                                                                                                                                                                                                                                                                                      +
                                                                                                                                                                                       IF NOT ats_has_workflow_authority(wf.ministry_id, wf.sector_id, 'override') THEN                                                                                                                                                                                                                                                                                                                                                              +
                                                                                                                                                                                             RAISE EXCEPTION 'Override authority required';                                                                                                                                                                                                                                                                                                                                                                                          +
                                                                                                                                                                                                 END IF;                                                                                                                                                                                                                                                                                                                                                                                                                             +
                                                                                                                                                                                                   END IF;                                                                                                                                                                                                                                                                                                                                                                                                                           +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                                                                                                                                                     -- Apply transition                                                                                                                                                                                                                                                                                                                                                                                                             +
                                                                                                                                                                                                       UPDATE ats_workflows                                                                                                                                                                                                                                                                                                                                                                                                          +
                                                                                                                                                                                                         SET state = p_to_state,                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                                                                                                                                                               updated_at = now()                                                                                                                                                                                                                                                                                                                                                                                                    +
                                                                                                                                                                                                                 WHERE id = p_workflow_id;                                                                                                                                                                                                                                                                                                                                                                                           +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                                                                                                                                                                   INSERT INTO ats_workflow_steps (                                                                                                                                                                                                                                                                                                                                                                                  +
                                                                                                                                                                                                                       workflow_id,                                                                                                                                                                                                                                                                                                                                                                                                  +
                                                                                                                                                                                                                           state,                                                                                                                                                                                                                                                                                                                                                                                                    +
                                                                                                                                                                                                                               actor_id,                                                                                                                                                                                                                                                                                                                                                                                             +
                                                                                                                                                                                                                                   note                                                                                                                                                                                                                                                                                                                                                                                              +
                                                                                                                                                                                                                                     )                                                                                                                                                                                                                                                                                                                                                                                               +
                                                                                                                                                                                                                                       VALUES (                                                                                                                                                                                                                                                                                                                                                                                      +
                                                                                                                                                                                                                                           p_workflow_id,                                                                                                                                                                                                                                                                                                                                                                            +
                                                                                                                                                                                                                                               p_to_state,                                                                                                                                                                                                                                                                                                                                                                           +
                                                                                                                                                                                                                                                   me,                                                                                                                                                                                                                                                                                                                                                                               +
                                                                                                                                                                                                                                                       p_note                                                                                                                                                                                                                                                                                                                                                                        +
                                                                                                                                                                                                                                                         );                                                                                                                                                                                                                                                                                                                                                                          +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                                                                                                                                                                                                           RETURN true;                                                                                                                                                                                                                                                                                                                                                              +
                                                                                                                                                                                                                                                           END;                                                                                                                                                                                                                                                                                                                                                                      +
                                                                                                                                                                                                                                                           $function$                                                                                                                                                                                                                                                                                                                                                                +
 
 CREATE OR REPLACE FUNCTION public.allocate_member(m_id uuid, tier text, priority text, u_id uuid, start_date date)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
  RETURNS allocations                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
  LANGUAGE plpgsql                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
 AS $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
                       declare                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
                           next_slot int;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
                               deadline date;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
                                   alloc allocations;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
                                   begin                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
                                       -- Compute next family slot                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
                                           select current_families + 1 into next_slot                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
                                               from units                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
                                                   where id = u_id;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                       -- Compute 15-month deadline                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
                                                           select (start_date + interval '15 months')::date into deadline;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                               -- Insert allocation                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
                                                                   insert into allocations (                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
                                                                           member_id,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
                                                                                   tier,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
                                                                                           priority,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +
                                                                                                   allocation_clock_start,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
                                                                                                           allocation_deadline,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
                                                                                                                   months_remaining,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +
                                                                                                                           unit_id,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
                                                                                                                                   family_slot,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
                                                                                                                                           allocation_status,                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
                                                                                                                                                   engine                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
                                                                                                                                                       )                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
                                                                                                                                                           values (                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
                                                                                                                                                                   m_id,                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
                                                                                                                                                                           tier,                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                                                                                                                                   priority,                                                                                                                                                                                                                                                                                                                                                                                                                                         +
                                                                                                                                                                                           start_date,                                                                                                                                                                                                                                                                                                                                                                                                                               +
                                                                                                                                                                                                   deadline,                                                                                                                                                                                                                                                                                                                                                                                                                         +
                                                                                                                                                                                                           15,                                                                                                                                                                                                                                                                                                                                                                                                                       +
                                                                                                                                                                                                                   u_id,                                                                                                                                                                                                                                                                                                                                                                                                             +
                                                                                                                                                                                                                           next_slot,                                                                                                                                                                                                                                                                                                                                                                                                +
                                                                                                                                                                                                                                   'Allocated',                                                                                                                                                                                                                                                                                                                                                                                      +
                                                                                                                                                                                                                                           'ATS-Allocation-RPC'                                                                                                                                                                                                                                                                                                                                                                      +
                                                                                                                                                                                                                                               )                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                                                                                                                                                                                                   returning * into alloc;                                                                                                                                                                                                                                                                                                                                                           +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                                                                                                                                                                                                       -- Update unit families                                                                                                                                                                                                                                                                                                                                                       +
                                                                                                                                                                                                                                                           update units                                                                                                                                                                                                                                                                                                                                                              +
                                                                                                                                                                                                                                                               set current_families = current_families + 1                                                                                                                                                                                                                                                                                                                           +
                                                                                                                                                                                                                                                                   where id = u_id;                                                                                                                                                                                                                                                                                                                                                  +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                                                                                                                                                                                                                       -- Update unit status                                                                                                                                                                                                                                                                                                                                         +
                                                                                                                                                                                                                                                                           update units                                                                                                                                                                                                                                                                                                                                              +
                                                                                                                                                                                                                                                                               set                                                                                                                                                                                                                                                                                                                                                   +
                                                                                                                                                                                                                                                                                       is_full = (current_families >= max_families),                                                                                                                                                                                                                                                                                                 +
                                                                                                                                                                                                                                                                                               unit_status = case                                                                                                                                                                                                                                                                                                                    +
                                                                                                                                                                                                                                                                                                           when current_families >= max_families then 'Full'                                                                                                                                                                                                                                                                         +
                                                                                                                                                                                                                                                                                                                       when current_families > 0 then 'Partially Allocated'                                                                                                                                                                                                                                                          +
                                                                                                                                                                                                                                                                                                                                   else 'Available'                                                                                                                                                                                                                                                                                  +
                                                                                                                                                                                                                                                                                                                                           end                                                                                                                                                                                                                                                                                       +
                                                                                                                                                                                                                                                                                                                                               where id = u_id;                                                                                                                                                                                                                                                                      +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                                                                                                                                                                                                                                                                                                   return alloc;                                                                                                                                                                                                                                                                     +
                                                                                                                                                                                                                                                                                                                                                   end;                                                                                                                                                                                                                                                                              +
                                                                                                                                                                                                                                                                                                                                                   $function$                                                                                                                                                                                                                                                                        +
 
 CREATE OR REPLACE FUNCTION public.approve_compliance_document(p_document_id uuid, p_ministry text)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
  RETURNS void                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
  LANGUAGE plpgsql                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
 AS $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
       begin                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
         update compliance_documents                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +
           set status = 'approved',                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
                 approved_by = p_ministry,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
                       approval_timestamp = now()                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
                         where id = p_document_id;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
                         end;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
                         $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
 
