 CREATE OR REPLACE FUNCTION public.approve_tax_reprieve(p_pdf_id uuid, p_ministry text)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
  RETURNS void                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
  LANGUAGE plpgsql                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
 AS $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
       begin                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
         update glyph_pdfs                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
           set approval_status = 'approved',                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
                 approved_by = p_ministry,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
                       approval_timestamp = now()                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
                         where id = p_pdf_id;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
                         end;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
                         $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
 
 CREATE OR REPLACE FUNCTION public.assign_severity()                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +
  RETURNS trigger                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
  LANGUAGE plpgsql                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
 AS $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
 declare                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
   assigned text;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
   begin                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
     if new.message ilike '%TypeError%' or new.message ilike '%ReferenceError%' then                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +
         assigned := 'high';                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
           elsif new.message ilike '%Warning%' then                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
               assigned := 'low';                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
                 else                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
                     assigned := 'medium';                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
                       end if;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                         -- If severity differs from what was provided, log it                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
                           if new.severity is distinct from assigned then                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
                               insert into error_severity_audit (error_id, old_severity, new_severity, reason)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
                                   values (new.id, new.severity, assigned, 'Auto-assigned based on message keywords');                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +
                                       new.severity := assigned;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                         end if;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                           return new;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +
                                           end;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
                                           $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
 
 CREATE OR REPLACE FUNCTION public.ats_cross_sector_influence()                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
  RETURNS json                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
  LANGUAGE sql                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
  SECURITY DEFINER                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
 AS $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
 WITH ordered_steps AS (                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
   SELECT                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
       s.workflow_id,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
           w.sector_id,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
               s.state,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
                   s.created_at,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                       ROW_NUMBER() OVER (PARTITION BY s.workflow_id ORDER BY s.created_at) AS rn                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
                         FROM ats_workflow_steps s                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
                           JOIN ats_workflows w ON w.id = s.workflow_id                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
                           ),                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                           transitions AS (                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
                             SELECT                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
                                 a.workflow_id,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
                                     a.sector_id AS from_sector,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                         b.sector_id AS to_sector                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
                                           FROM ordered_steps a                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
                                             JOIN ordered_steps b                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
                                                 ON a.workflow_id = b.workflow_id                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
                                                    AND a.rn + 1 = b.rn                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
                                                       AND a.sector_id <> b.sector_id   -- sector changed                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
                                                       )                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                       SELECT json_agg(                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
                                                         json_build_object(                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
                                                             'from_sector', t.from_sector,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
                                                                 'to_sector', t.to_sector,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
                                                                     'count', t.count                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
                                                                       )                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
                                                                       )                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
                                                                       FROM (                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
                                                                         SELECT                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
                                                                             from_sector,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
                                                                                 to_sector,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
                                                                                     COUNT(*) AS count                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +
                                                                                       FROM transitions                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
                                                                                         GROUP BY from_sector, to_sector                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
                                                                                           ORDER BY from_sector, to_sector                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
                                                                                           ) t;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
                                                                                           $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
 
 CREATE OR REPLACE FUNCTION public.ats_current_member_id()                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
  RETURNS uuid                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
  LANGUAGE sql                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
  SECURITY DEFINER                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
 AS $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
   SELECT m.id                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
     FROM ats_members m                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
       WHERE m.auth_user_id = auth.uid()                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
         LIMIT 1;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
         $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
 
 CREATE OR REPLACE FUNCTION public.ats_has_certificate_authority(p_level text, p_ministry_id uuid, p_sector_id uuid)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +
  RETURNS boolean                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
  LANGUAGE sql                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
  SECURITY DEFINER                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
 AS $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
           WITH me AS (                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
               SELECT ats_current_member_id() AS member_id                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
                 )                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
                   SELECT EXISTS (                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
                       SELECT 1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
                           FROM me                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
                               JOIN ats_certificate_authorities ca                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
                                     ON ca.member_id = me.member_id                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
                                         WHERE ca.level = p_level                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
                                               AND (ca.ministry_id IS NULL OR ca.ministry_id = p_ministry_id)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
                                                     AND (ca.sector_id   IS NULL OR ca.sector_id   = p_sector_id)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
                                                       );                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
                                                       $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
 
 CREATE OR REPLACE FUNCTION public.ats_has_permission(p_slug text)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
  RETURNS boolean                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
  LANGUAGE sql                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
  SECURITY DEFINER                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
 AS $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
   WITH me AS (                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
       SELECT ats_current_member_id() AS member_id                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
         )                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
           SELECT EXISTS (                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
               SELECT 1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
                   FROM me                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
                       JOIN ats_role_bindings rb                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                             ON rb.member_id = me.member_id                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
                                 JOIN ats_role_permissions rp                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
                                       ON rp.role_id = rb.role_id                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
                                           JOIN ats_permissions perm                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +
                                                 ON perm.id = rp.permission_id                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
                                                     WHERE perm.slug = p_slug                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
                                                           AND (rb.expires_at IS NULL OR rb.expires_at > now())                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
                                                             );                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
                                                             $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
 
 CREATE OR REPLACE FUNCTION public.ats_has_permission_for_scope(p_slug text, p_ministry_id uuid, p_sector_id uuid)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
  RETURNS boolean                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
  LANGUAGE sql                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
  SECURITY DEFINER                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
 AS $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
           WITH me AS (                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
               SELECT ats_current_member_id() AS member_id                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
                 )                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
                   SELECT EXISTS (                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
                       SELECT 1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
                           FROM me                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
                               JOIN ats_role_bindings rb                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
                                     ON rb.member_id = me.member_id                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
                                         JOIN ats_role_permissions rp                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
                                               ON rp.role_id = rb.role_id                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
                                                   JOIN ats_permissions perm                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
                                                         ON perm.id = rp.permission_id                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +
                                                             WHERE perm.slug = p_slug                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
                                                                   AND (rb.expires_at IS NULL OR rb.expires_at > now())                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
                                                                         AND (rb.ministry_id IS NULL OR rb.ministry_id = p_ministry_id)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
                                                                               AND (rb.sector_id   IS NULL OR rb.sector_id   = p_sector_id)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
                                                                                 );                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
                                                                                 $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
 
 CREATE OR REPLACE FUNCTION public.ats_has_workflow_authority(p_ministry_id uuid, p_sector_id uuid, p_action text)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
  RETURNS boolean                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
  LANGUAGE plpgsql                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
  SECURITY DEFINER                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
 AS $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
         DECLARE                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
           me uuid := ats_current_member_id();                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
             allowed boolean := false;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +
             BEGIN                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
               -- Ministry-level authority                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
                 SELECT true INTO allowed                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
                   FROM ats_member_roles                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
                     WHERE member_id = me                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
                         AND (ministry_id = p_ministry_id OR ministry_id IS NULL)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
                             AND (                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
                                   (p_action = 'initiate' AND role_code IN ('OFFICER','CLERK','MANAGER')) OR                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
                                         (p_action = 'approve'  AND role_code IN ('MANAGER','DIRECTOR')) OR                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
                                               (p_action = 'override' AND role_code IN ('DIRECTOR','PS','MINISTER'))                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +
                                                   )                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +
                                                     LIMIT 1;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                       RETURN COALESCE(allowed, false);                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
                                                       END;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
                                                       $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
 
 CREATE OR REPLACE FUNCTION public.ats_legitimacy_engine()                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
  RETURNS trigger                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
  LANGUAGE plpgsql                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
 AS $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
 declare                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
   entity text := TG_TABLE_NAME;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
     entity_id uuid := NEW.id;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
     begin                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
       -- Insert legitimacy event                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
         insert into audit_trail (                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
             entity_type,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
                 entity_id,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
                     action,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
                         actor_role,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +
                             actor_id,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +
                                 commentary                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
                                   ) values (                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
                                       entity,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
                                           entity_id,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
                                               TG_OP,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
                                                   current_setting('request.jwt.claims', true)::json->>'role',                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
                                                       current_setting('request.jwt.claims', true)::json->>'sub',                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
                                                           format('Legitimacy event: %s on %s', TG_OP, entity)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
                                                             );                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                               -- Update legitimacy influence index                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
                                                                 update legitimacy_influence                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
                                                                   set score = score + 1,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
                                                                         updated_at = now()                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
                                                                           where entity_type = entity                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
                                                                             and entity_id = entity_id;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                               -- Update legitimacy trust index                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
                                                                                 update legitimacy_trust                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
                                                                                   set trust = trust + 1,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
                                                                                         updated_at = now()                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
                                                                                           where entity_type = entity                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
                                                                                             and entity_id = entity_id;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                                               -- Update legitimacy anomaly detection                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
                                                                                                 insert into legitimacy_anomalies (                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
                                                                                                     entity_type,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
                                                                                                         entity_id,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
                                                                                                             anomaly_type,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
                                                                                                                 created_at                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
                                                                                                                   ) values (                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
                                                                                                                       entity,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
                                                                                                                           entity_id,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
                                                                                                                               'activity',                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
                                                                                                                                   now()                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
                                                                                                                                     );                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                                                                                       return NEW;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
                                                                                                                                       end $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
 
 CREATE OR REPLACE FUNCTION public.ats_sector_aging()                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
  RETURNS json                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
  LANGUAGE sql                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
  SECURITY DEFINER                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
 AS $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
 SELECT json_agg(                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
   json_build_object(                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
       'sector_id', t.sector_id,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
           'ages', t.ages                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
             )                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
             )                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
             FROM (                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
               SELECT                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
                   w.sector_id,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
                       (                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
                             SELECT json_agg(                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
                                     EXTRACT(EPOCH FROM (                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
                                               (SELECT MAX(created_at) FROM ats_workflow_steps s WHERE s.workflow_id = w.id)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
                                                         - w.created_at                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
                                                                 )) / 3600                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
                                                                       )                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
                                                                           ) AS ages                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +
                                                                             FROM ats_workflows w                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
                                                                               GROUP BY w.sector_id                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
                                                                                 ORDER BY w.sector_id                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
                                                                                 ) t;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
                                                                                 $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
 
 CREATE OR REPLACE FUNCTION public.ats_sector_decay_model()                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
  RETURNS json                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
  LANGUAGE sql                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
  SECURITY DEFINER                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
 AS $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
 WITH base AS (                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
   SELECT                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
       w.id AS workflow_id,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
           w.sector_id,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
               -- Age in hours                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
                   EXTRACT(EPOCH FROM (                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
                         (SELECT MAX(created_at)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                FROM ats_workflow_steps s                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
                                       WHERE s.workflow_id = w.id)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
                                             - w.created_at                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
                                                 )) / 3600 AS age_hours                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
                                                   FROM ats_workflows w                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
                                                   ),                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                   sector_load AS (                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
                                                     SELECT                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
                                                         sector_id,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
                                                             COUNT(*) AS load_count                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
                                                               FROM ats_workflows                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
                                                                 GROUP BY sector_id                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
                                                                 ),                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                 decay AS (                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
                                                                   SELECT                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
                                                                       b.sector_id,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
                                                                           b.workflow_id,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
                                                                               b.age_hours,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
                                                                                   sl.load_count,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
                                                                                       (b.age_hours * LOG(sl.load_count + 1)) AS decay_score                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
                                                                                         FROM base b                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +
                                                                                           JOIN sector_load sl ON sl.sector_id = b.sector_id                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
                                                                                           ),                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                                           aggregated AS (                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
                                                                                             SELECT                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
                                                                                                 sector_id,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
                                                                                                     AVG(age_hours) AS avg_age,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
                                                                                                         MAX(load_count) AS sector_load,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
                                                                                                             AVG(decay_score) AS avg_decay,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
                                                                                                                 MAX(decay_score) AS max_decay                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
                                                                                                                   FROM decay                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
                                                                                                                     GROUP BY sector_id                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
                                                                                                                     )                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                                                                     SELECT json_agg(                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
                                                                                                                       json_build_object(                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
                                                                                                                           'sector_id', a.sector_id,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +
                                                                                                                               'avg_age', a.avg_age,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +
                                                                                                                                   'sector_load', a.sector_load,                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                                                                                       'avg_decay', a.avg_decay,                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                                                                                           'max_decay', a.max_decay                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
                                                                                                                                             )                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
                                                                                                                                             )                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
                                                                                                                                             FROM aggregated a;                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
                                                                                                                                             $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
 
 CREATE OR REPLACE FUNCTION public.ats_sector_dependencies()                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
  RETURNS json                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
  LANGUAGE sql                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
  SECURITY DEFINER                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
 AS $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
 WITH ordered_steps AS (                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
   SELECT                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
       s.workflow_id,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
           w.sector_id,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
               s.state,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
                   s.created_at,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                       ROW_NUMBER() OVER (PARTITION BY s.workflow_id ORDER BY s.created_at) AS rn                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
                         FROM ats_workflow_steps s                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
                           JOIN ats_workflows w ON w.id = s.workflow_id                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
                           ),                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                           dependencies AS (                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
                             SELECT                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
                                 a.sector_id AS from_sector,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
                                     b.sector_id AS to_sector                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
                                       FROM ordered_steps a                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
                                         JOIN ordered_steps b                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
                                             ON a.workflow_id = b.workflow_id                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
                                                AND a.rn + 1 = b.rn                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
                                                   AND a.sector_id <> b.sector_id   -- sector changed                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
                                                   )                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                   SELECT json_agg(                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
                                                     json_build_object(                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
                                                         'from_sector', t.from_sector,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +
                                                             'to_sector', t.to_sector,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +
                                                                 'count', t.count                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
                                                                   )                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +
                                                                   )                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +
                                                                   FROM (                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
                                                                     SELECT                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
                                                                         from_sector,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
                                                                             to_sector,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
                                                                                 COUNT(*) AS count                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
                                                                                   FROM dependencies                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +
                                                                                     GROUP BY from_sector, to_sector                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +
                                                                                       ORDER BY from_sector, to_sector                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +
                                                                                       ) t;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
                                                                                       $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
 
 CREATE OR REPLACE FUNCTION public.ats_sector_heatmap()                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
  RETURNS json                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
  LANGUAGE sql                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
  SECURITY DEFINER                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
 AS $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
 SELECT json_build_object(                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
   'timestamp', now(),                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +
     'sectors', (                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
         SELECT json_agg(                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
               json_build_object(                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
                       'sector_id', t.sector_id,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                               'count', t.count                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
                                     )                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +
                                         )                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
                                             FROM (                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
                                                   SELECT sector_id, COUNT(*) AS count                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +
                                                         FROM ats_workflows                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
                                                               GROUP BY sector_id                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
                                                                     ORDER BY COUNT(*) DESC                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
                                                                         ) t                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
                                                                           )                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
                                                                           );                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
                                                                           $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
 
 CREATE OR REPLACE FUNCTION public.ats_sector_influence()                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
  RETURNS json                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
  LANGUAGE sql                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
  SECURITY DEFINER                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
 AS $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
 SELECT json_build_object(                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
   'timestamp', now(),                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +
     'sectors', (                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
         SELECT json_agg(                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
               json_build_object(                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
                       'sector_id', t.sector_id,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                               'influence_score', t.influence_score,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +
                                       'approvals', t.approvals,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                               'overrides', t.overrides,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
                                                       'rejections', t.rejections,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
                                                               'transitions', t.transitions                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
                                                                     )                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +
                                                                         )                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
                                                                             FROM (                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
                                                                                   SELECT                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
                                                                                           w.sector_id,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                                                   -- Count transitions by state movement                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
                                                                                                           (SELECT COUNT(*) FROM ats_workflow_steps s WHERE s.workflow_id = w.id) AS transitions,                                                                                                                                                                                                                                                                                                                                                                                                                                    +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                                                                   -- Count approvals                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
                                                                                                                           (SELECT COUNT(*) FROM ats_workflow_steps s WHERE s.workflow_id = w.id AND s.state = 'APPROVED') AS approvals,                                                                                                                                                                                                                                                                                                                                                                                             +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                                                                                   -- Count overrides                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
                                                                                                                                           (SELECT COUNT(*) FROM ats_workflow_steps s WHERE s.workflow_id = w.id AND s.state = 'OVERRIDDEN') AS overrides,                                                                                                                                                                                                                                                                                                                                                                           +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                                                                                                   -- Count rejections                                                                                                                                                                                                                                                                                                                                                                                                                                                               +
                                                                                                                                                           (SELECT COUNT(*) FROM ats_workflow_steps s WHERE s.workflow_id = w.id AND s.state = 'REJECTED') AS rejections,                                                                                                                                                                                                                                                                                                                                                            +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                                                                                                                   -- Influence score formula                                                                                                                                                                                                                                                                                                                                                                                                                                        +
                                                                                                                                                                           (                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
                                                                                                                                                                                     (SELECT COUNT(*) FROM ats_workflow_steps s WHERE s.workflow_id = w.id) * 1 +                                                                                                                                                                                                                                                                                                                                                                    +
                                                                                                                                                                                               (SELECT COUNT(*) FROM ats_workflow_steps s WHERE s.workflow_id = w.id AND s.state = 'APPROVED') * 3 +                                                                                                                                                                                                                                                                                                                                 +
                                                                                                                                                                                                         (SELECT COUNT(*) FROM ats_workflow_steps s WHERE s.workflow_id = w.id AND s.state = 'REJECTED') * 2 +                                                                                                                                                                                                                                                                                                                       +
                                                                                                                                                                                                                   (SELECT COUNT(*) FROM ats_workflow_steps s WHERE s.workflow_id = w.id AND s.state = 'OVERRIDDEN') * 5                                                                                                                                                                                                                                                                                                             +
                                                                                                                                                                                                                           ) AS influence_score                                                                                                                                                                                                                                                                                                                                                                                      +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                                                                                                                                                                                 FROM ats_workflows w                                                                                                                                                                                                                                                                                                                                                                                +
                                                                                                                                                                                                                                       GROUP BY w.sector_id, w.id                                                                                                                                                                                                                                                                                                                                                                    +
                                                                                                                                                                                                                                           ) t                                                                                                                                                                                                                                                                                                                                                                                       +
                                                                                                                                                                                                                                             )                                                                                                                                                                                                                                                                                                                                                                                       +
                                                                                                                                                                                                                                             );                                                                                                                                                                                                                                                                                                                                                                                      +
                                                                                                                                                                                                                                             $function$                                                                                                                                                                                                                                                                                                                                                                              +
 
 CREATE OR REPLACE FUNCTION public.ats_sector_recovery_model()                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
  RETURNS json                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
  LANGUAGE sql                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
  SECURITY DEFINER                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
 AS $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
 WITH steps AS (                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
   SELECT                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
       s.workflow_id,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
           w.sector_id,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
               s.created_at                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
                 FROM ats_workflow_steps s                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
                   JOIN ats_workflows w ON w.id = s.workflow_id                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
                   ),                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                   recent_activity AS (                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
                     SELECT                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
                         sector_id,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
                             COUNT(*) AS steps_24h                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
                               FROM steps                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
                                 WHERE created_at >= now() - INTERVAL '24 hours'                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                   GROUP BY sector_id                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
                                   ),                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                   weekly_activity AS (                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
                                     SELECT                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
                                         sector_id,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
                                             COUNT(*) AS steps_7d                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
                                               FROM steps                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
                                                 WHERE created_at >= now() - INTERVAL '7 days'                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
                                                   GROUP BY sector_id                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
                                                   ),                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                   base AS (                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
                                                     SELECT                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
                                                         w.id AS workflow_id,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
                                                             w.sector_id,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
                                                                 EXTRACT(EPOCH FROM (                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
                                                                       (SELECT MAX(created_at)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
                                                                              FROM ats_workflow_steps s                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
                                                                                     WHERE s.workflow_id = w.id)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                                           - w.created_at                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
                                                                                               )) / 3600 AS age_hours                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
                                                                                                 FROM ats_workflows w                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
                                                                                                 ),                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                                                 sector_load AS (                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
                                                                                                   SELECT                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
                                                                                                       sector_id,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
                                                                                                           COUNT(*) AS load_count                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
                                                                                                             FROM ats_workflows                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
                                                                                                               GROUP BY sector_id                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
                                                                                                               ),                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                                                               decay AS (                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
                                                                                                                 SELECT                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
                                                                                                                     b.sector_id,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
                                                                                                                         b.workflow_id,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
                                                                                                                             b.age_hours,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
                                                                                                                                 sl.load_count,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
                                                                                                                                     (b.age_hours * LOG(sl.load_count + 1)) AS decay_score                                                                                                                                                                                                                                                                                                                                                                                                                                           +
                                                                                                                                       FROM base b                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
                                                                                                                                         JOIN sector_load sl ON sl.sector_id = b.sector_id                                                                                                                                                                                                                                                                                                                                                                                                                                           +
                                                                                                                                         ),                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                                                                                         aggregated AS (                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
                                                                                                                                           SELECT                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
                                                                                                                                               d.sector_id,                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
                                                                                                                                                   AVG(d.decay_score) AS avg_decay,                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
                                                                                                                                                       MAX(d.load_count) AS sector_load,                                                                                                                                                                                                                                                                                                                                                                                                                                             +
                                                                                                                                                           COALESCE(r.steps_24h, 0) AS steps_24h,                                                                                                                                                                                                                                                                                                                                                                                                                                    +
                                                                                                                                                               COALESCE(w.steps_7d, 0) AS steps_7d                                                                                                                                                                                                                                                                                                                                                                                                                                   +
                                                                                                                                                                 FROM decay d                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
                                                                                                                                                                   LEFT JOIN recent_activity r ON r.sector_id = d.sector_id                                                                                                                                                                                                                                                                                                                                                                                                          +
                                                                                                                                                                     LEFT JOIN weekly_activity w ON w.sector_id = d.sector_id                                                                                                                                                                                                                                                                                                                                                                                                        +
                                                                                                                                                                       GROUP BY d.sector_id, r.steps_24h, w.steps_7d                                                                                                                                                                                                                                                                                                                                                                                                                 +
                                                                                                                                                                       )                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                                                                                                                       SELECT json_agg(                                                                                                                                                                                                                                                                                                                                                                                                                                              +
                                                                                                                                                                         json_build_object(                                                                                                                                                                                                                                                                                                                                                                                                                                          +
                                                                                                                                                                             'sector_id', a.sector_id,                                                                                                                                                                                                                                                                                                                                                                                                                               +
                                                                                                                                                                                 'avg_decay', a.avg_decay,                                                                                                                                                                                                                                                                                                                                                                                                                           +
                                                                                                                                                                                     'sector_load', a.sector_load,                                                                                                                                                                                                                                                                                                                                                                                                                   +
                                                                                                                                                                                         'steps_24h', a.steps_24h,                                                                                                                                                                                                                                                                                                                                                                                                                   +
                                                                                                                                                                                             'steps_7d', a.steps_7d,                                                                                                                                                                                                                                                                                                                                                                                                                 +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                                                                                                                                                 'recovery_acceleration',                                                                                                                                                                                                                                                                                                                                                                                                            +
                                                                                                                                                                                                       CASE                                                                                                                                                                                                                                                                                                                                                                                                                          +
                                                                                                                                                                                                               WHEN a.steps_7d = 0 THEN 0                                                                                                                                                                                                                                                                                                                                                                                            +
                                                                                                                                                                                                                       ELSE (a.steps_24h::float / a.steps_7d::float)                                                                                                                                                                                                                                                                                                                                                                 +
                                                                                                                                                                                                                             END,                                                                                                                                                                                                                                                                                                                                                                                                    +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                                                                                                                                                                                 'recovery_score',                                                                                                                                                                                                                                                                                                                                                                                   +
                                                                                                                                                                                                                                       100                                                                                                                                                                                                                                                                                                                                                                                           +
                                                                                                                                                                                                                                             + (COALESCE(a.steps_24h, 0) * 0.5)                                                                                                                                                                                                                                                                                                                                                      +
                                                                                                                                                                                                                                                   + (CASE WHEN a.steps_7d = 0 THEN 0 ELSE (a.steps_24h::float / a.steps_7d::float) * 20 END)                                                                                                                                                                                                                                                                                        +
                                                                                                                                                                                                                                                         - (a.avg_decay * 0.4)                                                                                                                                                                                                                                                                                                                                                       +
                                                                                                                                                                                                                                                           )                                                                                                                                                                                                                                                                                                                                                                         +
                                                                                                                                                                                                                                                           )                                                                                                                                                                                                                                                                                                                                                                         +
                                                                                                                                                                                                                                                           FROM aggregated a;                                                                                                                                                                                                                                                                                                                                                        +
                                                                                                                                                                                                                                                           $function$                                                                                                                                                                                                                                                                                                                                                                +
 
 CREATE OR REPLACE FUNCTION public.ats_sector_resilience()                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
  RETURNS json                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
  LANGUAGE sql                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
  SECURITY DEFINER                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
 AS $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
 WITH base AS (                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
   SELECT                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
       w.sector_id,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
           -- SLA hours                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
               EXTRACT(EPOCH FROM (                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
                     (SELECT MAX(created_at) FROM ats_workflow_steps s WHERE s.workflow_id = w.id)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
                           - w.created_at                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
                               )) / 3600 AS sla_hours,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                   -- Aging hours (same as SLA)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
                                       EXTRACT(EPOCH FROM (                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
                                             (SELECT MAX(created_at) FROM ats_workflow_steps s WHERE s.workflow_id = w.id)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
                                                   - w.created_at                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
                                                       )) / 3600 AS aging_hours,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                           -- Influence score (transitions)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
                                                               (SELECT COUNT(*) FROM ats_workflow_steps s WHERE s.workflow_id = w.id) AS influence_score                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
                                                                 FROM ats_workflows w                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
                                                                 ),                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                 aggregated AS (                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                   SELECT                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
                                                                       sector_id,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
                                                                           AVG(sla_hours) AS avg_sla,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
                                                                               AVG(aging_hours) AS avg_aging,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
                                                                                   SUM(influence_score) AS total_influence,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
                                                                                       COUNT(*) AS workflow_count                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
                                                                                         FROM base                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
                                                                                           GROUP BY sector_id                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
                                                                                           ),                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                                           dependencies AS (                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
                                                                                             SELECT                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
                                                                                                 a.sector_id AS from_sector,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
                                                                                                     COUNT(*) AS dependency_count                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
                                                                                                       FROM ats_workflow_steps s                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                                                         JOIN ats_workflows a ON a.id = s.workflow_id                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
                                                                                                           GROUP BY a.sector_id                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
                                                                                                           )                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                                                           SELECT json_agg(                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
                                                                                                             json_build_object(                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
                                                                                                                 'sector_id', a.sector_id,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
                                                                                                                     'avg_sla', a.avg_sla,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
                                                                                                                         'avg_aging', a.avg_aging,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
                                                                                                                             'total_influence', a.total_influence,                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
                                                                                                                                 'dependency_count', COALESCE(d.dependency_count, 0),                                                                                                                                                                                                                                                                                                                                                                                                                                                +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                                                                                     'resilience_score',                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
                                                                                                                                           100                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
                                                                                                                                                 - (a.avg_sla * 0.5)                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +
                                                                                                                                                       - (a.avg_aging * 0.3)                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
                                                                                                                                                             + (a.total_influence * 0.2)                                                                                                                                                                                                                                                                                                                                                                                                                                             +
                                                                                                                                                                   - (COALESCE(d.dependency_count, 0) * 0.1)                                                                                                                                                                                                                                                                                                                                                                                                                         +
                                                                                                                                                                     )                                                                                                                                                                                                                                                                                                                                                                                                                                                               +
                                                                                                                                                                     )                                                                                                                                                                                                                                                                                                                                                                                                                                                               +
                                                                                                                                                                     FROM aggregated a                                                                                                                                                                                                                                                                                                                                                                                                                                               +
                                                                                                                                                                     LEFT JOIN dependencies d ON d.from_sector = a.sector_id;                                                                                                                                                                                                                                                                                                                                                                                                        +
                                                                                                                                                                     $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
 
 CREATE OR REPLACE FUNCTION public.ats_sector_segmentation()                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
  RETURNS json                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
  LANGUAGE sql                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
  SECURITY DEFINER                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
 AS $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
 SELECT json_agg(                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
   json_build_object(                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
       'sector_id', t.sector_id,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
           'count', t.count                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
             )                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
             )                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
             FROM (                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
               SELECT sector_id, COUNT(*) AS count                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
                 FROM ats_workflows                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
                   GROUP BY sector_id                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
                     ORDER BY COUNT(*) DESC                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
                     ) t;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
                     $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
 
 CREATE OR REPLACE FUNCTION public.ats_sector_sla()                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
  RETURNS json                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
  LANGUAGE sql                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
  SECURITY DEFINER                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
 AS $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
 SELECT json_agg(                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
   json_build_object(                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
       'sector_id', t.sector_id,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
           'avg_hours', t.avg_hours,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +
               'max_hours', t.max_hours,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
                   'breaches', t.breaches,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
                       'total', t.total                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
                         )                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
                         )                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
                         FROM (                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
                           SELECT                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
                               w.sector_id,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                   -- Average SLA in hours                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
                                       AVG(                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
                                             EXTRACT(EPOCH FROM (                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
                                                     (SELECT MAX(created_at) FROM ats_workflow_steps s WHERE s.workflow_id = w.id)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
                                                             -                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
                                                                     w.created_at                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
                                                                           )) / 3600                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +
                                                                               ) AS avg_hours,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                                   -- Maximum SLA in hours                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
                                                                                       MAX(                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
                                                                                             EXTRACT(EPOCH FROM (                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
                                                                                                     (SELECT MAX(created_at) FROM ats_workflow_steps s WHERE s.workflow_id = w.id)                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
                                                                                                             -                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
                                                                                                                     w.created_at                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
                                                                                                                           )) / 3600                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +
                                                                                                                               ) AS max_hours,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                                                                                   -- SLA breaches (over 48 hours)                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
                                                                                                                                       COUNT(*) FILTER (                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
                                                                                                                                             WHERE EXTRACT(EPOCH FROM (                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
                                                                                                                                                     (SELECT MAX(created_at) FROM ats_workflow_steps s WHERE s.workflow_id = w.id)                                                                                                                                                                                                                                                                                                                                                                                                   +
                                                                                                                                                             -                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
                                                                                                                                                                     w.created_at                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
                                                                                                                                                                           )) / 3600 > 48                                                                                                                                                                                                                                                                                                                                                                                                                                            +
                                                                                                                                                                               ) AS breaches,                                                                                                                                                                                                                                                                                                                                                                                                                                        +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                                                                                                                                   COUNT(*) AS total                                                                                                                                                                                                                                                                                                                                                                                                                                 +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                                                                                                                                     FROM ats_workflows w                                                                                                                                                                                                                                                                                                                                                                                                                            +
                                                                                                                                                                                       GROUP BY w.sector_id                                                                                                                                                                                                                                                                                                                                                                                                                          +
                                                                                                                                                                                         ORDER BY w.sector_id                                                                                                                                                                                                                                                                                                                                                                                                                        +
                                                                                                                                                                                         ) t;                                                                                                                                                                                                                                                                                                                                                                                                                                        +
                                                                                                                                                                                         $function$                                                                                                                                                                                                                                                                                                                                                                                                                                  +
 
 CREATE OR REPLACE FUNCTION public.ats_sector_stability_index()                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
  RETURNS json                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
  LANGUAGE sql                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
  SECURITY DEFINER                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
 AS $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
 WITH latest_steps AS (                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
   SELECT                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
       w.id AS workflow_id,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
           w.sector_id,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
               w.created_at AS workflow_created_at,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
                   (SELECT MAX(created_at)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
                        FROM ats_workflow_steps s                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
                             WHERE s.workflow_id = w.id) AS last_step_time                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
                               FROM ats_workflows w                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
                               ),                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                               metrics AS (                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
                                 SELECT                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
                                     workflow_id,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
                                         sector_id,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
                                             workflow_created_at,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
                                                 last_step_time,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                     EXTRACT(EPOCH FROM (last_step_time - workflow_created_at)) / 3600 AS age_hours,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +
                                                         EXTRACT(EPOCH FROM (now() - last_step_time)) / 3600 AS stall_hours                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
                                                           FROM latest_steps                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
                                                           ),                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                           escalation AS (                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
                                                             SELECT                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
                                                                 workflow_id,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
                                                                     sector_id,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
                                                                         age_hours,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
                                                                             stall_hours,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
                                                                                 CASE                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
                                                                                       WHEN stall_hours > 36 THEN 4                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
                                                                                             WHEN age_hours > 72 THEN 3                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
                                                                                                   WHEN age_hours > 48 THEN 2                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
                                                                                                         WHEN age_hours > 24 THEN 1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
                                                                                                               ELSE 0                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
                                                                                                                   END AS escalation_level                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
                                                                                                                     FROM metrics                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
                                                                                                                     ),                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                                                                     sector_load AS (                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
                                                                                                                       SELECT                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
                                                                                                                           sector_id,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
                                                                                                                               COUNT(*) AS load_count                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
                                                                                                                                 FROM ats_workflows                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
                                                                                                                                   GROUP BY sector_id                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
                                                                                                                                   ),                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                                                                                   decay AS (                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
                                                                                                                                     SELECT                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
                                                                                                                                         m.sector_id,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
                                                                                                                                             m.workflow_id,                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
                                                                                                                                                 m.age_hours,                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
                                                                                                                                                     sl.load_count,                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
                                                                                                                                                         (m.age_hours * LOG(sl.load_count + 1)) AS decay_score                                                                                                                                                                                                                                                                                                                                                                                                                       +
                                                                                                                                                           FROM metrics m                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
                                                                                                                                                             JOIN sector_load sl ON sl.sector_id = m.sector_id                                                                                                                                                                                                                                                                                                                                                                                                                       +
                                                                                                                                                             ),                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                                                                                                             aggregated AS (                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
                                                                                                                                                               SELECT                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
                                                                                                                                                                   d.sector_id,                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
                                                                                                                                                                       AVG(d.age_hours) AS avg_age,                                                                                                                                                                                                                                                                                                                                                                                                                                  +
                                                                                                                                                                           AVG(d.decay_score) AS avg_decay,                                                                                                                                                                                                                                                                                                                                                                                                                          +
                                                                                                                                                                               MAX(d.load_count) AS sector_load,                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                                                                                                                                   AVG(CASE WHEN e.escalation_level >= 2 THEN 1 ELSE 0 END) AS escalation_rate                                                                                                                                                                                                                                                                                                                                                                       +
                                                                                                                                                                                     FROM decay d                                                                                                                                                                                                                                                                                                                                                                                                                                    +
                                                                                                                                                                                       JOIN escalation e ON e.workflow_id = d.workflow_id                                                                                                                                                                                                                                                                                                                                                                                            +
                                                                                                                                                                                         GROUP BY d.sector_id                                                                                                                                                                                                                                                                                                                                                                                                                        +
                                                                                                                                                                                         )                                                                                                                                                                                                                                                                                                                                                                                                                                           +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                                                                                                                                         SELECT json_agg(                                                                                                                                                                                                                                                                                                                                                                                                                            +
                                                                                                                                                                                           json_build_object(                                                                                                                                                                                                                                                                                                                                                                                                                        +
                                                                                                                                                                                               'sector_id', a.sector_id,                                                                                                                                                                                                                                                                                                                                                                                                             +
                                                                                                                                                                                                   'avg_age', a.avg_age,                                                                                                                                                                                                                                                                                                                                                                                                             +
                                                                                                                                                                                                       'avg_decay', a.avg_decay,                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                                                                                                                                                           'sector_load', a.sector_load,                                                                                                                                                                                                                                                                                                                                                                                             +
                                                                                                                                                                                                               'escalation_rate', a.escalation_rate,                                                                                                                                                                                                                                                                                                                                                                                 +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                                                                                                                                                                   'stability_index',                                                                                                                                                                                                                                                                                                                                                                                                +
                                                                                                                                                                                                                         100                                                                                                                                                                                                                                                                                                                                                                                                         +
                                                                                                                                                                                                                               - (a.avg_decay * 0.4)                                                                                                                                                                                                                                                                                                                                                                                 +
                                                                                                                                                                                                                                     - (a.avg_age * 0.3)                                                                                                                                                                                                                                                                                                                                                                             +
                                                                                                                                                                                                                                           - (a.escalation_rate * 100 * 0.2)                                                                                                                                                                                                                                                                                                                                                         +
                                                                                                                                                                                                                                                 + (LOG(a.sector_load + 1) * 0.1)                                                                                                                                                                                                                                                                                                                                                    +
                                                                                                                                                                                                                                                   )                                                                                                                                                                                                                                                                                                                                                                                 +
                                                                                                                                                                                                                                                   )                                                                                                                                                                                                                                                                                                                                                                                 +
                                                                                                                                                                                                                                                   FROM aggregated a;                                                                                                                                                                                                                                                                                                                                                                +
                                                                                                                                                                                                                                                   $function$                                                                                                                                                                                                                                                                                                                                                                        +
 
 CREATE OR REPLACE FUNCTION public.ats_sector_timeline()                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
  RETURNS json                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
  LANGUAGE sql                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
  SECURITY DEFINER                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
 AS $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
 SELECT json_build_object(                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
   'timestamp', now(),                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +
     'timeline', (                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
         SELECT json_agg(                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
               json_build_object(                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
                       'sector_id', sector_id,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
                               'days', (                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
                                         SELECT json_agg(                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
                                                     json_build_object(                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
                                                                   'day', t.day,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                                 'count', t.count                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
                                                                                             )                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
                                                                                                       )                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
                                                                                                                 FROM (                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
                                                                                                                             SELECT to_char(created_at, 'YYYY-MM-DD') AS day,                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
                                                                                                                                                COUNT(*) AS count                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
                                                                                                                                                            FROM ats_workflows w2                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
                                                                                                                                                                        WHERE w2.sector_id = w1.sector_id                                                                                                                                                                                                                                                                                                                                                                                                                            +
                                                                                                                                                                                      AND created_at > now() - interval '30 days'                                                                                                                                                                                                                                                                                                                                                                                                    +
                                                                                                                                                                                                  GROUP BY to_char(created_at, 'YYYY-MM-DD')                                                                                                                                                                                                                                                                                                                                                                                         +
                                                                                                                                                                                                              ORDER BY day                                                                                                                                                                                                                                                                                                                                                                                                           +
                                                                                                                                                                                                                        ) t                                                                                                                                                                                                                                                                                                                                                                                                          +
                                                                                                                                                                                                                                )                                                                                                                                                                                                                                                                                                                                                                                                    +
                                                                                                                                                                                                                                      )                                                                                                                                                                                                                                                                                                                                                                                              +
                                                                                                                                                                                                                                          )                                                                                                                                                                                                                                                                                                                                                                                          +
                                                                                                                                                                                                                                              FROM (                                                                                                                                                                                                                                                                                                                                                                                 +
                                                                                                                                                                                                                                                    SELECT DISTINCT sector_id                                                                                                                                                                                                                                                                                                                                                        +
                                                                                                                                                                                                                                                          FROM ats_workflows                                                                                                                                                                                                                                                                                                                                                         +
                                                                                                                                                                                                                                                              ) w1                                                                                                                                                                                                                                                                                                                                                                   +
                                                                                                                                                                                                                                                                )                                                                                                                                                                                                                                                                                                                                                                    +
                                                                                                                                                                                                                                                                );                                                                                                                                                                                                                                                                                                                                                                   +
                                                                                                                                                                                                                                                                $function$                                                                                                                                                                                                                                                                                                                                                           +
 
 CREATE OR REPLACE FUNCTION public.ats_workflow_charts()                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
  RETURNS json                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
  LANGUAGE sql                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
  SECURITY DEFINER                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
 AS $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
 SELECT json_build_object(                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
   -- State distribution                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
     'states', (                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
         SELECT json_agg(                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
               json_build_object(                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
                       'state', t.state,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
                               'count', t.count                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
                                     )                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +
                                         )                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
                                             FROM (                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
                                                   SELECT state, COUNT(*) AS count                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
                                                         FROM ats_workflows                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
                                                               GROUP BY state                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
                                                                     ORDER BY COUNT(*) DESC                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
                                                                         ) t                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
                                                                           ),                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                             -- Workflows created per day (last 14 days)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
                                                                               'daily', (                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
                                                                                   SELECT json_agg(                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
                                                                                         json_build_object(                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
                                                                                                 'day', t.day,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
                                                                                                         'count', t.count                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
                                                                                                               )                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                                                                   )                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +
                                                                                                                       FROM (                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
                                                                                                                             SELECT to_char(created_at, 'YYYY-MM-DD') AS day,                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
                                                                                                                                          COUNT(*) AS count                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
                                                                                                                                                FROM ats_workflows                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
                                                                                                                                                      WHERE created_at > now() - interval '14 days'                                                                                                                                                                                                                                                                                                                                                                                                                                  +
                                                                                                                                                            GROUP BY to_char(created_at, 'YYYY-MM-DD')                                                                                                                                                                                                                                                                                                                                                                                                                               +
                                                                                                                                                                  ORDER BY day                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
                                                                                                                                                                      ) t                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
                                                                                                                                                                        ),                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                                                                                                                          -- Ministry segmentation                                                                                                                                                                                                                                                                                                                                                                                                                                   +
                                                                                                                                                                            'ministries', (                                                                                                                                                                                                                                                                                                                                                                                                                                          +
                                                                                                                                                                                SELECT json_agg(                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                                                                                                                                      json_build_object(                                                                                                                                                                                                                                                                                                                                                                                                                             +
                                                                                                                                                                                              'ministry_id', t.ministry_id,                                                                                                                                                                                                                                                                                                                                                                                                          +
                                                                                                                                                                                                      'count', t.count                                                                                                                                                                                                                                                                                                                                                                                                               +
                                                                                                                                                                                                            )                                                                                                                                                                                                                                                                                                                                                                                                                        +
                                                                                                                                                                                                                )                                                                                                                                                                                                                                                                                                                                                                                                                    +
                                                                                                                                                                                                                    FROM (                                                                                                                                                                                                                                                                                                                                                                                                           +
                                                                                                                                                                                                                          SELECT ministry_id, COUNT(*) AS count                                                                                                                                                                                                                                                                                                                                                                      +
                                                                                                                                                                                                                                FROM ats_workflows                                                                                                                                                                                                                                                                                                                                                                                   +
                                                                                                                                                                                                                                      GROUP BY ministry_id                                                                                                                                                                                                                                                                                                                                                                           +
                                                                                                                                                                                                                                            ORDER BY COUNT(*) DESC                                                                                                                                                                                                                                                                                                                                                                   +
                                                                                                                                                                                                                                                ) t                                                                                                                                                                                                                                                                                                                                                                                  +
                                                                                                                                                                                                                                                  )                                                                                                                                                                                                                                                                                                                                                                                  +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                                                                                                                                                                                                  );                                                                                                                                                                                                                                                                                                                                                                                 +
                                                                                                                                                                                                                                                  $function$                                                                                                                                                                                                                                                                                                                                                                         +
 
 CREATE OR REPLACE FUNCTION public.ats_workflow_dashboard()                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
  RETURNS json                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
  LANGUAGE sql                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
  SECURITY DEFINER                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
 AS $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
 SELECT json_build_object(                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
   'total', (SELECT COUNT(*) FROM ats_workflows),                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
     'by_state', (                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
         SELECT json_agg(                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
               json_build_object('state', state, 'count', count)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                   )                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +
                       FROM (                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
                             SELECT state, COUNT(*) AS count                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
                                   FROM ats_workflows                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
                                         GROUP BY state                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
                                               ORDER BY count DESC                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
                                                   ) t                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +
                                                     ),                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                       'recent', (                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
                                                           SELECT json_agg(                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
                                                                 json_build_object(                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
                                                                         'id', id,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
                                                                                 'state', state,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                                         'created_at', created_at,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
                                                                                                 'ministry_id', ministry_id,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
                                                                                                         'sector_id', sector_id                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
                                                                                                               )                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                                                                   )                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +
                                                                                                                       FROM (                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
                                                                                                                             SELECT id, state, created_at, ministry_id, sector_id                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
                                                                                                                                   FROM ats_workflows                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
                                                                                                                                         ORDER BY created_at DESC                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
                                                                                                                                               LIMIT 20                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
                                                                                                                                                   ) r                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +
                                                                                                                                                     )                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +
                                                                                                                                                     );                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
                                                                                                                                                     $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
 
 CREATE OR REPLACE FUNCTION public.ats_workflow_escalation_engine()                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
  RETURNS json                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
  LANGUAGE sql                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
  SECURITY DEFINER                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
 AS $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
 WITH latest_steps AS (                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
   SELECT                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
       w.id AS workflow_id,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
           w.sector_id,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
               w.created_at AS workflow_created_at,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
                   (SELECT MAX(created_at)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
                        FROM ats_workflow_steps s                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
                             WHERE s.workflow_id = w.id) AS last_step_time                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
                               FROM ats_workflows w                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
                               ),                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                               metrics AS (                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
                                 SELECT                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
                                     workflow_id,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
                                         sector_id,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
                                             workflow_created_at,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
                                                 last_step_time,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                     -- Total age                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
                                                         EXTRACT(EPOCH FROM (last_step_time - workflow_created_at)) / 3600 AS age_hours,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                             -- Time since last movement                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
                                                                 EXTRACT(EPOCH FROM (now() - last_step_time)) / 3600 AS stall_hours                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
                                                                   FROM latest_steps                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +
                                                                   ),                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                   escalation AS (                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
                                                                     SELECT                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
                                                                         workflow_id,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
                                                                             sector_id,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
                                                                                 age_hours,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
                                                                                     stall_hours,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                                         CASE                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
                                                                                               WHEN stall_hours > 36 THEN 4      -- stalled                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
                                                                                                     WHEN age_hours > 72 THEN 3        -- critical                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
                                                                                                           WHEN age_hours > 48 THEN 2        -- breach                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +
                                                                                                                 WHEN age_hours > 24 THEN 1        -- warning                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
                                                                                                                       ELSE 0                            -- normal                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
                                                                                                                           END AS escalation_level,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                                                                               CASE                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
                                                                                                                                     WHEN stall_hours > 36 THEN 'Stalled >36 hrs'                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
                                                                                                                                           WHEN age_hours > 72 THEN 'Critical aging >72 hrs'                                                                                                                                                                                                                                                                                                                                                                                                                                         +
                                                                                                                                                 WHEN age_hours > 48 THEN 'SLA breach >48 hrs'                                                                                                                                                                                                                                                                                                                                                                                                                                       +
                                                                                                                                                       WHEN age_hours > 24 THEN 'Warning aging 24–48 hrs'                                                                                                                                                                                                                                                                                                                                                                                                                            +
                                                                                                                                                             ELSE 'Normal'                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
                                                                                                                                                                 END AS reason                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
                                                                                                                                                                   FROM metrics                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
                                                                                                                                                                   )                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                                                                                                                   SELECT json_agg(                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
                                                                                                                                                                     json_build_object(                                                                                                                                                                                                                                                                                                                                                                                                                                              +
                                                                                                                                                                         'workflow_id', e.workflow_id,                                                                                                                                                                                                                                                                                                                                                                                                                               +
                                                                                                                                                                             'sector_id', e.sector_id,                                                                                                                                                                                                                                                                                                                                                                                                                               +
                                                                                                                                                                                 'age_hours', e.age_hours,                                                                                                                                                                                                                                                                                                                                                                                                                           +
                                                                                                                                                                                     'stall_hours', e.stall_hours,                                                                                                                                                                                                                                                                                                                                                                                                                   +
                                                                                                                                                                                         'escalation_level', e.escalation_level,                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                                                                                                                                             'reason', e.reason                                                                                                                                                                                                                                                                                                                                                                                                                      +
                                                                                                                                                                                               )                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                                                                                                                                               )                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                                                                                                                                               FROM escalation e;                                                                                                                                                                                                                                                                                                                                                                                                                    +
                                                                                                                                                                                               $function$                                                                                                                                                                                                                                                                                                                                                                                                                            +
 
 CREATE OR REPLACE FUNCTION public.ats_workflow_sla_alerts()                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
  RETURNS json                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
  LANGUAGE sql                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
  SECURITY DEFINER                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
 AS $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
 WITH ages AS (                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
   SELECT                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
       w.id AS workflow_id,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
           w.sector_id,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
               EXTRACT(EPOCH FROM (                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
                     (SELECT MAX(created_at) FROM ats_workflow_steps s WHERE s.workflow_id = w.id)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
                           - w.created_at                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
                               )) / 3600 AS age_hours                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
                                 FROM ats_workflows w                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
                                 )                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                 SELECT json_build_object(                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
                                   'timestamp', now(),                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                     'warning', (                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
                                         SELECT json_agg(                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
                                               json_build_object(                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
                                                       'workflow_id', a.workflow_id,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +
                                                               'sector_id', a.sector_id,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
                                                                       'age_hours', a.age_hours                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
                                                                             )                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
                                                                                 )                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
                                                                                     FROM ages a                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                                         WHERE a.age_hours BETWEEN 24 AND 48                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
                                                                                           ),                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                                             'breach', (                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
                                                                                                 SELECT json_agg(                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
                                                                                                       json_build_object(                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
                                                                                                               'workflow_id', a.workflow_id,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
                                                                                                                       'sector_id', a.sector_id,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                                                                               'age_hours', a.age_hours                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
                                                                                                                                     )                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +
                                                                                                                                         )                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
                                                                                                                                             FROM ages a                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
                                                                                                                                                 WHERE a.age_hours > 48                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
                                                                                                                                                   ),                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                                                                                                     'critical', (                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
                                                                                                                                                         SELECT json_agg(                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
                                                                                                                                                               json_build_object(                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
                                                                                                                                                                       'workflow_id', a.workflow_id,                                                                                                                                                                                                                                                                                                                                                                                                                                 +
                                                                                                                                                                               'sector_id', a.sector_id,                                                                                                                                                                                                                                                                                                                                                                                                                             +
                                                                                                                                                                                       'age_hours', a.age_hours                                                                                                                                                                                                                                                                                                                                                                                                                      +
                                                                                                                                                                                             )                                                                                                                                                                                                                                                                                                                                                                                                                                       +
                                                                                                                                                                                                 )                                                                                                                                                                                                                                                                                                                                                                                                                                   +
                                                                                                                                                                                                     FROM ages a                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                                                                                                                                                         WHERE a.age_hours > 72                                                                                                                                                                                                                                                                                                                                                                                                      +
                                                                                                                                                                                                           )                                                                                                                                                                                                                                                                                                                                                                                                                         +
                                                                                                                                                                                                           );                                                                                                                                                                                                                                                                                                                                                                                                                        +
                                                                                                                                                                                                           $function$                                                                                                                                                                                                                                                                                                                                                                                                                +
 
 CREATE OR REPLACE FUNCTION public.audit_lineage_logs()                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
  RETURNS trigger                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
  LANGUAGE plpgsql                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
 AS $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
 DECLARE                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
   v_actor UUID;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
   BEGIN                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
     -- Try to capture user ID, fallback to system UUID                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
       v_actor := COALESCE(auth.uid(), '00000000-0000-0000-0000-000000000000');                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
         IF TG_OP = 'INSERT' THEN                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
             INSERT INTO lineage_audit(lineage_id, branch, blessing, action, actor)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
                 VALUES (NEW.id, NEW.branch, NEW.blessing, 'INSERT', v_actor);                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
                     RETURN NEW;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                       ELSIF TG_OP = 'UPDATE' THEN                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
                           INSERT INTO lineage_audit(lineage_id, branch, blessing, action, actor)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
                               VALUES (NEW.id, NEW.branch, NEW.blessing, 'UPDATE', v_actor);                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
                                   RETURN NEW;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
                                     ELSIF TG_OP = 'DELETE' THEN                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                         INSERT INTO lineage_audit(lineage_id, branch, blessing, action, actor)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
                                             VALUES (OLD.id, OLD.branch, OLD.blessing, 'DELETE', v_actor);                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
                                                 RETURN OLD;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
                                                   END IF;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
                                                   END;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
                                                   $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
 
 CREATE OR REPLACE FUNCTION public.can_approve_workflow(p_ministry_id uuid, p_sector_id uuid)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
  RETURNS boolean                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
  LANGUAGE plpgsql                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
  SECURITY DEFINER                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
 AS $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
       DECLARE                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
         me uuid := ats_current_member_id();                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
         BEGIN                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
           RETURN EXISTS (                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
               SELECT 1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
                   FROM ats_workflow_authorities wa                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
                       WHERE wa.member_id = me                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
                             AND (wa.ministry_id IS NULL OR wa.ministry_id = p_ministry_id)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
                                   AND (wa.sector_id   IS NULL OR wa.sector_id   = p_sector_id)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
                                         AND wa.can_approve = true                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
                                           );                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
                                           END;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
                                           $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
 
 CREATE OR REPLACE FUNCTION public.can_issue_certificate(p_level text, p_ministry_id uuid, p_sector_id uuid)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
  RETURNS boolean                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
  LANGUAGE plpgsql                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
  SECURITY DEFINER                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
 AS $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
         DECLARE                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
           me uuid := ats_current_member_id();                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
           BEGIN                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
             RETURN EXISTS (                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
                 SELECT 1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
                     FROM ats_certificate_authorities ca                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
                         WHERE ca.member_id = me                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                               AND ca.level = p_level                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
                                     AND (ca.ministry_id IS NULL OR ca.ministry_id = p_ministry_id)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
                                           AND (ca.sector_id   IS NULL OR ca.sector_id   = p_sector_id)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
                                             );                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
                                             END;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
                                             $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
 
 CREATE OR REPLACE FUNCTION public.commission_legitimacy(role_name text)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
  RETURNS void                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
  LANGUAGE plpgsql                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
  SECURITY DEFINER                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
 AS $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
 declare                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
   uid uuid := auth.uid();                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
   begin                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
     update legitimacy                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +
       set progress = 100,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
             stage = 'commissioned',                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +
                   updated_at = now()                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
                     where user_id = uid                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
                         and role = role_name;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
                         end;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
                         $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
 
 CREATE OR REPLACE FUNCTION public.create_index_if_missing(idx_name text, tbl_name text, idx_sql text)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +
  RETURNS void                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
  LANGUAGE plpgsql                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
 AS $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
       begin                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
         if not exists (                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
             select 1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
                 from pg_indexes                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                     where indexname = idx_name                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
                       ) then                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
                           execute idx_sql;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
                             end if;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +
                             end $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
 
 CREATE OR REPLACE FUNCTION public.create_workflow(p_ministry_id uuid, p_sector_id uuid, p_title text, p_payload jsonb)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
  RETURNS uuid                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
  LANGUAGE plpgsql                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
  SECURITY DEFINER                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
 AS $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
         DECLARE                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
           me uuid := ats_current_member_id();                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
             wf_id uuid;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
             BEGIN                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
               INSERT INTO ats_workflows (                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
                   ministry_id,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
                       sector_id,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
                           state,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
                               created_by,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
                                   title,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
                                       payload                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
                                         )                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
                                           VALUES (                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
                                               p_ministry_id,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
                                                   p_sector_id,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
                                                       'DRAFT',                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
                                                           me,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
                                                               p_title,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
                                                                   p_payload                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
                                                                     )                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +
                                                                       RETURNING id INTO wf_id;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                         INSERT INTO ats_workflow_steps (                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
                                                                             workflow_id,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
                                                                                 state,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
                                                                                     actor_id,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
                                                                                         note                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
                                                                                           )                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
                                                                                             VALUES (                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
                                                                                                 wf_id,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
                                                                                                     'DRAFT',                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
                                                                                                         me,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
                                                                                                             'Workflow created'                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
                                                                                                               );                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                                                                 RETURN wf_id;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
                                                                                                                 END;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
