  LANGUAGE sql                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
  STABLE                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
 AS $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
