 CREATE OR REPLACE FUNCTION public.emit_workflow_event(p_event_type text, p_event_payload jsonb)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
  RETURNS void                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
  LANGUAGE plpgsql                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
  SECURITY DEFINER                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
 AS $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
 declare                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
   v_ministry_id uuid;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +
 begin                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +
   -- Resolve ministry_id from JWT ministry name                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
   select id into v_ministry_id                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
   from ministries                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
   where name = auth.jwt()->>'ministry';                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
   insert into workflow_events (                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
     user_id,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
     stakeholder,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
     ministry,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
     ministry_id,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
     event_type,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
     event_payload                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
   )                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +
   values (                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
     auth.uid(),                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
     auth.jwt()->>'stakeholder',                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
     auth.jwt()->>'ministry',                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
     v_ministry_id,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
     p_event_type,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
     p_event_payload                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +
   );                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
 end;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
 $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
 
 CREATE OR REPLACE FUNCTION public.execute_sql_base64(sql_base64 text)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +
  RETURNS json                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
  LANGUAGE plpgsql                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
  SECURITY DEFINER                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
 AS $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
 declare                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
     decoded_sql text;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +
     begin                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
         decoded_sql := convert_from(decode(sql_base64, 'base64'), 'UTF8');                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
             execute decoded_sql;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
                 return json_build_object('status', 'ok');                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
                 exception                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
                     when others then                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
                             return json_build_object(                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +
                                         'status', 'error',                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
                                                     'message', SQLERRM,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
                                                                 'sql', decoded_sql                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
                                                                         );                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
                                                                         end;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
                                                                         $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
 
 CREATE OR REPLACE FUNCTION public.export_audit_logs()                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +
  RETURNS void                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
  LANGUAGE plpgsql                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
 AS $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
 declare                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
   logs jsonb;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
   begin                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
     -- Collect last week's logs                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
       select jsonb_agg(row_to_json(a)) into logs                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
         from audit_trail a                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
           where timestamp > now() - interval '7 days';                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
             -- Insert into a storage bucket for download                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
               insert into exports (file_name, file_content, created_at)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
                 values (                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
                     'audit_trail_' || to_char(now(), 'YYYYMMDD') || '.json',                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
                         logs,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
                             now()                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
                               );                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
                               end;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
                               $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
 
 CREATE OR REPLACE FUNCTION public.export_lineage_audit_csv()                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
  RETURNS SETOF text                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +
  LANGUAGE plpgsql                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
 AS $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
 BEGIN                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +
   RETURN QUERY                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
     SELECT                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
         lineage_id || ',' || branch || ',' || blessing || ',' || action || ',' || created_at                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
           FROM lineage_audit                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
             ORDER BY created_at DESC;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +
             END;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
             $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
 
 CREATE OR REPLACE FUNCTION public.federation_heartbeat(node_id uuid)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
  RETURNS void                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
  LANGUAGE plpgsql                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
 AS $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
 declare                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
   n record;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
     new_sync int;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
       new_trust int;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
         new_health int;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
         begin                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
           select * into n from federation_nodes where id = node_id;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
             -- Sync increases slightly with each heartbeat                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
               new_sync := least(100, n.sync_level + 5);                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                 -- Trust adjusts based on sync                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
                   new_trust := least(100, n.trust_index + (new_sync - n.sync_level) / 2);                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                     -- Health adjusts based on trust + sync                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
                       new_health := least(100, n.federation_health + ((new_trust + new_sync) / 40));                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                         -- Update node                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
                           update federation_nodes                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
                             set                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                 sync_level = new_sync,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
                                     trust_index = new_trust,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
                                         federation_health = new_health,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
                                             last_sync_at = now(),                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
                                                 is_in_sync = new_sync >= 70                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
                                                   where id = node_id;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                     -- Log heartbeat                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
                                                       insert into federation_heartbeat (                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
                                                           node_id,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
                                                               node_label,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
                                                                   sync_before,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
                                                                       sync_after,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
                                                                           trust_before,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
                                                                               trust_after,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
                                                                                   health_before,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
                                                                                       health_after                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
                                                                                         )                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
                                                                                           values (                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
                                                                                               n.id,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +
                                                                                                   n.node_label,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                                                       n.sync_level,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +
                                                                                                           new_sync,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +
                                                                                                               n.trust_index,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
                                                                                                                   new_trust,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
                                                                                                                       n.federation_health,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
                                                                                                                           new_health                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
                                                                                                                             );                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
                                                                                                                             end;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
                                                                                                                             $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
 
 CREATE OR REPLACE FUNCTION public.federation_heartbeat_all()                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
  RETURNS void                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
  LANGUAGE plpgsql                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
 AS $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
 declare                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
   n record;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
   begin                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
     for n in select id from federation_nodes loop                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
         perform federation_heartbeat(n.id);                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
           end loop;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +
           end;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
           $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
 
 CREATE OR REPLACE FUNCTION public.federation_heartbeat_timeline()                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
  RETURNS jsonb                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
  LANGUAGE sql                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
 AS $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
 select jsonb_agg(                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
   jsonb_build_object(                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +
       'node_label', node_label,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
           'sync_before', sync_before,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +
               'sync_after', sync_after,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
                   'trust_before', trust_before,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                       'trust_after', trust_after,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
                           'health_before', health_before,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
                               'health_after', health_after,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
                                   'heartbeat_time', heartbeat_time                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
                                     )                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +
                                     )                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +
                                     from (                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
                                       select *                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
                                         from federation_heartbeat                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
                                           order by heartbeat_time desc                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
                                           ) t;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
                                           $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
 
 CREATE OR REPLACE FUNCTION public.federation_sync_index()                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
  RETURNS TABLE(node_label text, sync_level integer, last_sync_at timestamp with time zone, is_in_sync boolean, global_sync_index numeric)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
  LANGUAGE sql                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
 AS $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
           with stats as (                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
             select avg(sync_level) as avg_sync                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
               from federation_nodes                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +
               )                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
               select                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
                 node_label,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
                   sync_level,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
                     last_sync_at,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
                       is_in_sync,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
                         stats.avg_sync as global_sync_index                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
                         from federation_nodes, stats;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +
                         $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
 
 CREATE OR REPLACE FUNCTION public.federation_vitality_ai()                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
  RETURNS TABLE(node_label text, federation_health integer, trust_index integer, sync_level integer, heartbeat_count integer, last_heartbeat timestamp with time zone, vitality_score numeric)                                                                                                                                                                                                                                                                                                                                                                                                                                       +
  LANGUAGE sql                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
 AS $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
               with hb_stats as (                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
                 select                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
                     node_id,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
                         count(*) as heartbeat_count,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
                             max(heartbeat_time) as last_heartbeat                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
                               from federation_heartbeat                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
                                 group by node_id                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
                                 )                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
                                 select                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
                                   n.node_label,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                     n.federation_health,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
                                       n.trust_index,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
                                         n.sync_level,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +
                                           coalesce(hb.heartbeat_count, 0) as heartbeat_count,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
                                             hb.last_heartbeat,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
                                               (                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                   n.federation_health * 0.4 +                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
                                                       n.trust_index * 0.3 +                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
                                                           n.sync_level * 0.2 +                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
                                                               coalesce(hb.heartbeat_count, 0) * 0.1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +
                                                                 ) as vitality_score                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +
                                                                 from federation_nodes n                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
                                                                 left join hb_stats hb                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +
                                                                   on hb.node_id = n.id;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
                                                                   $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
 
 CREATE OR REPLACE FUNCTION public.generate_certificate()                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
  RETURNS trigger                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
  LANGUAGE plpgsql                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
 AS $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
                                       BEGIN                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
                                         IF NEW.progress_stage = 5 THEN                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
                                             UPDATE feedback                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
                                                 SET certificate_url = 'https://portal.example.com/certificates/' || NEW.id,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
                                                         submitted_at = NOW()                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
                                                             WHERE stakeholder_id = NEW.id;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
                                                               END IF;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +
                                                                 RETURN NEW;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
                                                                 END;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
                                                                 $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
 
