 CREATE OR REPLACE FUNCTION public.get_dashboard_metrics()                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
  RETURNS json                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
  LANGUAGE plpgsql                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
  SECURITY DEFINER                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
 AS $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
 declare                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
   members_count bigint;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
     institutions_count bigint;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
       communities_count bigint;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
         councils_count bigint;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
           govt_count bigint;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
             savings_count bigint;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
               payments_total numeric(12,2);                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
                 certificates_count bigint;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
                 begin                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +
                   if not public.is_staff() then                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                       raise exception 'Not allowed';                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
                         end if;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                           select count(*) into members_count from public.members;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
                             select count(*) into institutions_count from public.institutions;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
                               select count(*) into communities_count from public.communities;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
                                 select count(*) into councils_count from public.councils;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
                                   select count(*) into govt_count from public.govt_departments;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                     select count(*) into savings_count from public.savings_plans;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
                                       select coalesce(sum(amount),0) into payments_total from public.payments;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
                                         select count(*) into certificates_count from public.certificates;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                           return json_build_object(                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +
                                               'members', members_count,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
                                                   'institutions', institutions_count,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +
                                                       'communities', communities_count,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
                                                           'councils', councils_count,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +
                                                               'government', govt_count,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
                                                                   'savings_plans', savings_count,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
                                                                       'payments_total', payments_total,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
                                                                           'certificates', certificates_count                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
                                                                             );                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
                                                                             end;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
                                                                             $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
 
 CREATE OR REPLACE FUNCTION public.get_dimensional_stability()                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
  RETURNS TABLE(id bigint, node_label text, stability_index integer, coherence_index integer, drift_index integer, pressure_index integer, arc_label text, x_pos integer, y_pos integer)                                                                                                                                                                                                                                                                                                                                                                                                                                             +
  LANGUAGE sql                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
 AS $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
                     select                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
                         id, node_label, stability_index, coherence_index, drift_index, pressure_index, arc_label, x_pos, y_pos                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
                           from dimensional_stability                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
                             order by stability_index desc;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
                             $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
 
 CREATE OR REPLACE FUNCTION public.get_export_record(record_id uuid)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +
  RETURNS jsonb                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
  LANGUAGE plpgsql                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
  SECURITY DEFINER                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
 AS $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
 declare                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
   result jsonb;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
   begin                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
     select jsonb_build_object(                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
         'id', e.id,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +
             'product', e.product,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
                 'destination_country', e.destination_country,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
                     'volume_tons', e.volume_tons,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
                         'revenue', e.revenue,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
                             'ats_verified', e.ats_verified,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
                                 'updated_at', e.updated_at                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
                                   )                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +
                                     into result                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                       from export_intelligence e                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
                                         where e.id = record_id;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                           return result;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
                                           end;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
                                           $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
 
 CREATE OR REPLACE FUNCTION public.get_federation_gnss_points()                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
  RETURNS TABLE(node_label text, lat numeric, lng numeric, accuracy numeric, gnss_timestamp text)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
  LANGUAGE sql                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
 AS $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
           select                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
             node_label,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
               (gnss->>'lat')::numeric as lat,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
                 (gnss->>'lng')::numeric as lng,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                   (gnss->>'accuracy')::numeric as accuracy,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
                     gnss->>'timestamp' as gnss_timestamp                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
                     from federation_nodes                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
                     where gnss is not null;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
                     $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
 
 CREATE OR REPLACE FUNCTION public.get_federation_state()                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
  RETURNS jsonb                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
  LANGUAGE sql                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
 AS $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
 select jsonb_agg(                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
   jsonb_build_object(                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +
       'id', id,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
           'node_label', node_label,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +
               'federation_health', federation_health,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +
                   'trust_index', trust_index,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
                       'sync_level', sync_level,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                           'x_pos', x_pos,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
                               'y_pos', y_pos,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
                                   'link_to', link_to,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +
                                       'gnss', gnss                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
                                         )                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
                                         )                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
                                         from federation_nodes;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
                                         $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
 
