 CREATE OR REPLACE FUNCTION public.get_member_allocation_summary(m_id uuid)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
  RETURNS TABLE(member_id uuid, full_name text, tier text, priority text, unit_code text, block_name text, family_slot integer, allocation_status text, allocation_clock_start date, allocation_deadline date, months_remaining integer)                                                                                                                                                                                                                                                                                                                                                                                             +
  LANGUAGE sql                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
 AS $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
                                                 select                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
                                                         a.member_id,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
                                                                 m.full_name,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
                                                                         a.tier,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                                 a.priority,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
                                                                                         u.unit_code,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
                                                                                                 u.block_name,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
                                                                                                         a.family_slot,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
                                                                                                                 a.allocation_status,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
                                                                                                                         a.allocation_clock_start,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
                                                                                                                                 a.allocation_deadline,                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
                                                                                                                                         a.months_remaining                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
                                                                                                                                             from allocations a                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
                                                                                                                                                 join members m on m.id = a.member_id                                                                                                                                                                                                                                                                                                                                                                                                                                                +
                                                                                                                                                     join units u on u.id = a.unit_id                                                                                                                                                                                                                                                                                                                                                                                                                                                +
                                                                                                                                                         where a.member_id = m_id;                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
                                                                                                                                                         $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
 
 CREATE OR REPLACE FUNCTION public.get_member_profile(member_id uuid)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
  RETURNS json                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
  LANGUAGE plpgsql                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
  SECURITY DEFINER                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
 AS $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
 declare                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
   result json;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
   begin                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
     if not public.is_staff() then                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
         raise exception 'Not allowed';                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
           end if;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
             select json_build_object(                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +
                 'member', row_to_json(m),                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
                     'savings_plans', (                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
                           select coalesce(json_agg(row_to_json(s)), '[]'::json)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                 from public.savings_plans s                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
                                       where s.member_id = m.id                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
                                           ),                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
                                               'payments', (                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
                                                     select coalesce(json_agg(row_to_json(p)), '[]'::json)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
                                                           from public.payments p                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
                                                                 where p.payer_type = 'member'                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
                                                                       and p.payer_id = m.id                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
                                                                           ),                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
                                                                               'certificates', (                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                                     select coalesce(json_agg(row_to_json(c)), '[]'::json)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
                                                                                           from public.certificates c                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
                                                                                                 where c.holder_type = 'member'                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
                                                                                                       and c.holder_id = m.id                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
                                                                                                           )                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
                                                                                                             )                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
                                                                                                               into result                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
                                                                                                                 from public.members m                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +
                                                                                                                   where m.id = member_id;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                                                                     return result;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
                                                                                                                     end;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
                                                                                                                     $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
 
