                                                     'mechanisation_id', m.mechanisation_id,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
                                                         'gnss_job_id', m.gnss_job_id                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
                                                           )                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
                                                             into result                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
                                                               from ministries m                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                 where m.id = ministry_id;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                   return result;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
                                                                   end;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
                                                                   $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
 
