 CREATE OR REPLACE FUNCTION public.get_payment_job(job_id uuid)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
  RETURNS jsonb                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
  LANGUAGE plpgsql                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
  SECURITY DEFINER                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
 AS $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
 declare                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
   result jsonb;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
   begin                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
     select jsonb_build_object(                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
         'id', p.id,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +
             'amount', p.amount,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                 'currency', p.currency,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
                     'status', p.status,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
                         'created_at', p.created_at,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +
