                                 'provider', p.provider,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
                                     'reference', p.reference,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
                                         'callback_url', p.callback_url,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
                                             'retry_count', p.retry_count,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
