 CREATE OR REPLACE FUNCTION public.get_payment_profile(payment_id uuid)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
  RETURNS json                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
  LANGUAGE plpgsql                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
  SECURITY DEFINER                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
 AS $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
 declare                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
   payment json;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
   begin                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
     if not public.is_staff() then                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
         raise exception 'Not allowed';                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
           end if;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
             select row_to_json(p)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
               into payment                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
                 from public.payments p                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
                   where p.id = payment_id;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                     return json_build_object(                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
                         'payment', payment                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
                           );                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
                           end;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
                           $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
 
 CREATE OR REPLACE FUNCTION public.get_procurement_record(record_id uuid, record_type text)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
  RETURNS jsonb                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
  LANGUAGE plpgsql                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
  SECURITY DEFINER                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
 AS $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
 declare                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
   result jsonb;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
   begin                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
     --------------------------------------------------------------------                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
       -- EXPORT PROCUREMENT                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
         --------------------------------------------------------------------                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
           if record_type = 'export' then                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
               select jsonb_build_object(                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
                     'type', 'export',                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +
                           'id', e.id,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +
                                 'product', e.product,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +
                                       'intake_kg', e.volume_tons,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
                                             'revenue', e.revenue,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
                                                   'status', e.status,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +
                                                         'created_at', e.updated_at,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                               -- Coordinator (stakeholder)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
                                                                     'coordinator_id', sp.id,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
                                                                           'coordinator_name', sp.full_name,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                                 -- Community (destination)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
                                                                                       'community_name', c.name,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                                             'community_id', c.id,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                                                   -- Institution (exporting ministry)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +
                                                                                                         'institution_id', i.id,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                                                               'institution_name', i.name,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                                                                     -- Ledger                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
                                                                                                                           'ledger_id', le.id,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
                                                                                                                                 'ledger_description', le.description                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
                                                                                                                                     )                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +
                                                                                                                                         into result                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +
                                                                                                                                             from export_intelligence e                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
                                                                                                                                                 left join stakeholder_profiles sp on sp.id = e.coordinator_id                                                                                                                                                                                                                                                                                                                                                                                                                       +
                                                                                                                                                     left join communities c on c.name = e.destination_country                                                                                                                                                                                                                                                                                                                                                                                                                       +
                                                                                                                                                         left join institutions i on i.id = e.institution_id                                                                                                                                                                                                                                                                                                                                                                                                                         +
                                                                                                                                                             left join ledger_entries le on le.reference_id = e.id::text                                                                                                                                                                                                                                                                                                                                                                                                             +
                                                                                                                                                                 where e.id = record_id;                                                                                                                                                                                                                                                                                                                                                                                                                                             +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                                                                                                                     return result;                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
                                                                                                                                                                       end if;                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                                                                                                                         --------------------------------------------------------------------                                                                                                                                                                                                                                                                                                                                                                                        +
                                                                                                                                                                           -- AGRICULTURE PROCUREMENT                                                                                                                                                                                                                                                                                                                                                                                                                                +
                                                                                                                                                                             --------------------------------------------------------------------                                                                                                                                                                                                                                                                                                                                                                                    +
                                                                                                                                                                               if record_type = 'agriculture' then                                                                                                                                                                                                                                                                                                                                                                                                                   +
                                                                                                                                                                                   select jsonb_build_object(                                                                                                                                                                                                                                                                                                                                                                                                                        +
                                                                                                                                                                                         'type', 'agriculture',                                                                                                                                                                                                                                                                                                                                                                                                                      +
                                                                                                                                                                                               'id', a.id,                                                                                                                                                                                                                                                                                                                                                                                                                           +
                                                                                                                                                                                                     'farmer_name', a.full_name,                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                                                                                                                                                           'community_name', a.community_name,                                                                                                                                                                                                                                                                                                                                                                                       +
                                                                                                                                                                                                                 'intake_kg', a.yield_tonnage,                                                                                                                                                                                                                                                                                                                                                                                       +
                                                                                                                                                                                                                       'crop_type', a.crop_type,                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                                                                                                                                                                             'livestock_count', a.livestock_count,                                                                                                                                                                                                                                                                                                                                                                   +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                                                                                                                                                                                   -- Federation                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                                                                                                                                                                                         'community_id', c.id,                                                                                                                                                                                                                                                                                                                                                                       +
                                                                                                                                                                                                                                               'institution_id', i.id,                                                                                                                                                                                                                                                                                                                                                               +
                                                                                                                                                                                                                                                     'ledger_id', le.id                                                                                                                                                                                                                                                                                                                                                              +
                                                                                                                                                                                                                                                         )                                                                                                                                                                                                                                                                                                                                                                           +
                                                                                                                                                                                                                                                             into result                                                                                                                                                                                                                                                                                                                                                             +
                                                                                                                                                                                                                                                                 from agriculture_production a                                                                                                                                                                                                                                                                                                                                       +
                                                                                                                                                                                                                                                                     left join communities c on c.name = a.community_name                                                                                                                                                                                                                                                                                                            +
                                                                                                                                                                                                                                                                         left join institutions i on i.sector = 'Agriculture'                                                                                                                                                                                                                                                                                                        +
                                                                                                                                                                                                                                                                             left join ledger_entries le on le.reference_id = a.id::text                                                                                                                                                                                                                                                                                             +
                                                                                                                                                                                                                                                                                 where a.id = record_id;                                                                                                                                                                                                                                                                                                                             +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                                                                                                                                                                                                                                     return result;                                                                                                                                                                                                                                                                                                                                  +
                                                                                                                                                                                                                                                                                       end if;                                                                                                                                                                                                                                                                                                                                       +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                                                                                                                                                                                                                                         --------------------------------------------------------------------                                                                                                                                                                                                                                                                        +
                                                                                                                                                                                                                                                                                           -- COMMUNITY HOUSING PROCUREMENT                                                                                                                                                                                                                                                                                                          +
                                                                                                                                                                                                                                                                                             --------------------------------------------------------------------                                                                                                                                                                                                                                                                    +
                                                                                                                                                                                                                                                                                               if record_type = 'community' then                                                                                                                                                                                                                                                                                                     +
                                                                                                                                                                                                                                                                                                   select jsonb_build_object(                                                                                                                                                                                                                                                                                                        +
                                                                                                                                                                                                                                                                                                         'type', 'community',                                                                                                                                                                                                                                                                                                        +
                                                                                                                                                                                                                                                                                                               'id', cm.id,                                                                                                                                                                                                                                                                                                          +
                                                                                                                                                                                                                                                                                                                     'member_name', cm.full_name,                                                                                                                                                                                                                                                                                    +
                                                                                                                                                                                                                                                                                                                           'community_id', cm.community_id,                                                                                                                                                                                                                                                                          +
                                                                                                                                                                                                                                                                                                                                 'role', cm.role,                                                                                                                                                                                                                                                                                    +
                                                                                                                                                                                                                                                                                                                                       'pledge', cm.pledge,                                                                                                                                                                                                                                                                          +
                                                                                                                                                                                                                                                                                                                                             'status', cm.status,                                                                                                                                                                                                                                                                    +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                                                                                                                                                                                                                                                                                                   -- Federation                                                                                                                                                                                                                                                                     +
                                                                                                                                                                                                                                                                                                                                                         'community_name', c.name,                                                                                                                                                                                                                                                   +
                                                                                                                                                                                                                                                                                                                                                               'institution_id', i.id,                                                                                                                                                                                                                                               +
                                                                                                                                                                                                                                                                                                                                                                     'ledger_id', le.id                                                                                                                                                                                                                                              +
                                                                                                                                                                                                                                                                                                                                                                         )                                                                                                                                                                                                                                                           +
                                                                                                                                                                                                                                                                                                                                                                             into result                                                                                                                                                                                                                                             +
                                                                                                                                                                                                                                                                                                                                                                                 from community_members cm                                                                                                                                                                                                                           +
                                                                                                                                                                                                                                                                                                                                                                                     left join communities c on c.id = cm.community_id                                                                                                                                                                                               +
                                                                                                                                                                                                                                                                                                                                                                                         left join institutions i on i.sector = 'Housing'                                                                                                                                                                                            +
                                                                                                                                                                                                                                                                                                                                                                                             left join ledger_entries le on le.reference_id = cm.id::text                                                                                                                                                                            +
                                                                                                                                                                                                                                                                                                                                                                                                 where cm.id = record_id;                                                                                                                                                                                                            +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                                                                                                                                                                                                                                                                                                                                                     return result;                                                                                                                                                                                                                  +
                                                                                                                                                                                                                                                                                                                                                                                                       end if;                                                                                                                                                                                                                       +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                                                                                                                                                                                                                                                                                                                                                         --------------------------------------------------------------------                                                                                                                                                        +
                                                                                                                                                                                                                                                                                                                                                                                                           -- MINING PROCUREMENT                                                                                                                                                                                                     +
                                                                                                                                                                                                                                                                                                                                                                                                             --------------------------------------------------------------------                                                                                                                                                    +
                                                                                                                                                                                                                                                                                                                                                                                                               if record_type = 'mining' then                                                                                                                                                                                        +
                                                                                                                                                                                                                                                                                                                                                                                                                   select jsonb_build_object(                                                                                                                                                                                        +
                                                                                                                                                                                                                                                                                                                                                                                                                         'type', 'mining',                                                                                                                                                                                           +
                                                                                                                                                                                                                                                                                                                                                                                                                               'id', s.id,                                                                                                                                                                                           +
                                                                                                                                                                                                                                                                                                                                                                                                                                     'stakeholder_name', s.full_name,                                                                                                                                                                +
                                                                                                                                                                                                                                                                                                                                                                                                                                           'sector', s.sector,                                                                                                                                                                       +
                                                                                                                                                                                                                                                                                                                                                                                                                                                 'mechanisation_count', s.mechanisation_count,                                                                                                                                       +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                                                                                                                                                                                                                                                                                                                                                                                                       -- Federation                                                                                                                                                                 +
                                                                                                                                                                                                                                                                                                                                                                                                                                                             'institution_id', s.institution_id,                                                                                                                                     +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                   'ledger_id', le.id                                                                                                                                                +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                       )                                                                                                                                                             +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                           into result                                                                                                                                               +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                               from stakeholder_profiles s                                                                                                                           +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   left join ledger_entries le on le.reference_id = s.id::text                                                                                       +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       where s.id = record_id;                                                                                                                       +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           return result;                                                                                                                            +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             end if;                                                                                                                                 +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               --------------------------------------------------------------------                                                                  +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 -- INSURANCE PROCUREMENT                                                                                                            +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   --------------------------------------------------------------------                                                              +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     if record_type = 'insurance' then                                                                                               +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         select jsonb_build_object(                                                                                                  +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               'type', 'insurance',                                                                                                  +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     'id', sp.id,                                                                                                    +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           'full_name', sp.full_name,                                                                                +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 'sector', sp.sector,                                                                                +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       'legitimacy_score', sp.legitimacy_score,                                                      +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             -- Federation                                                                           +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   'institution_id', sp.institution_id,                                              +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         'ledger_id', le.id                                                          +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             )                                                                       +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 into result                                                         +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     from stakeholder_profiles sp                                    +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         left join ledger_entries le on le.reference_id = sp.id::text+
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             where sp.id = record_id;                                +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 return result;                                      +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   end if;                                           +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     return null;                                    +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     end;                                            +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     $function$                                      +
 
 CREATE OR REPLACE FUNCTION public.get_procurement_record(record_id uuid)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
  RETURNS jsonb                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
  LANGUAGE plpgsql                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
  SECURITY DEFINER                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
 AS $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
 declare                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
   result jsonb;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
   begin                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
     select jsonb_build_object(                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
         -- Core export/procurement fields                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
             'id', e.id,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
                 'product', e.product,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +
                     'destination_country', e.destination_country,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
                         'intake_kg', e.volume_tons,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +
                             'bags', ceil(e.volume_tons / 50.0),                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                 'revenue', e.revenue,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +
                                     'created_at', e.created_at,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                         'status', e.status,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                             -- REAL coordinator (from stakeholder_profiles)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
                                                 'coordinator_id', e.coordinator_id,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +
                                                     'coordinator_name', spc.full_name,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                         -- REAL farmer (from stakeholder_profiles or community_members)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
                                                             'farmer_id', e.farmer_id,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +
                                                                 'farmer_name', spf.full_name,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                     -- REAL community                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +
                                                                         'community_id', e.community_id,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
                                                                             'community_name', c.name,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                                 -- REAL institution                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +
                                                                                     'institution_id', e.institution_id,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
                                                                                         'institution_name', i.name,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                                             -- REAL ledger                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
                                                                                                 'ledger_id', e.ledger_entry_id,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                                                     'ledger_description', le.description,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
                                                                                                         'ledger_amount_usd', i.amount_usd,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                                                             -- Cumulative stats (still computed)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
                                                                                                                 'coordinator_total', (                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
                                                                                                                       select sum(volume_tons)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
                                                                                                                             from export_intelligence                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
                                                                                                                                   where coordinator_id = e.coordinator_id                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
                                                                                                                                       ),                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
                                                                                                                                           'farmer_total', (                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
                                                                                                                                                 select sum(volume_tons)                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
                                                                                                                                                       from export_intelligence                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
                                                                                                                                                             where farmer_id = e.farmer_id                                                                                                                                                                                                                                                                                                                                                                                                                                           +
                                                                                                                                                                 ),                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
                                                                                                                                                                     'daily_average', (                                                                                                                                                                                                                                                                                                                                                                                                                                              +
                                                                                                                                                                           select avg(volume_tons)                                                                                                                                                                                                                                                                                                                                                                                                                                   +
                                                                                                                                                                                 from export_intelligence                                                                                                                                                                                                                                                                                                                                                                                                                            +
                                                                                                                                                                                     )                                                                                                                                                                                                                                                                                                                                                                                                                                               +
                                                                                                                                                                                       )                                                                                                                                                                                                                                                                                                                                                                                                                                             +
                                                                                                                                                                                         into result                                                                                                                                                                                                                                                                                                                                                                                                                                 +
                                                                                                                                                                                           from export_intelligence e                                                                                                                                                                                                                                                                                                                                                                                                                +
                                                                                                                                                                                             left join stakeholder_profiles spc                                                                                                                                                                                                                                                                                                                                                                                                      +
                                                                                                                                                                                                 on spc.id = e.coordinator_id                                                                                                                                                                                                                                                                                                                                                                                                        +
                                                                                                                                                                                                   left join stakeholder_profiles spf                                                                                                                                                                                                                                                                                                                                                                                                +
                                                                                                                                                                                                       on spf.id = e.farmer_id                                                                                                                                                                                                                                                                                                                                                                                                       +
                                                                                                                                                                                                         left join communities c                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                                                                                                                                                             on c.id = e.community_id                                                                                                                                                                                                                                                                                                                                                                                                +
                                                                                                                                                                                                               left join institutions i                                                                                                                                                                                                                                                                                                                                                                                              +
                                                                                                                                                                                                                   on i.id = e.institution_id                                                                                                                                                                                                                                                                                                                                                                                        +
                                                                                                                                                                                                                     left join ledger_entries le                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                                                                                                                                                                         on le.id = e.ledger_entry_id                                                                                                                                                                                                                                                                                                                                                                                +
                                                                                                                                                                                                                           where e.id = record_id;                                                                                                                                                                                                                                                                                                                                                                                   +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                                                                                                                                                                             return result;                                                                                                                                                                                                                                                                                                                                                                                          +
                                                                                                                                                                                                                             end;                                                                                                                                                                                                                                                                                                                                                                                                    +
                                                                                                                                                                                                                             $function$                                                                                                                                                                                                                                                                                                                                                                                              +
 
 CREATE OR REPLACE FUNCTION public.get_quantum_kernel()                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
  RETURNS TABLE(id bigint, kernel_label text, arc_label text, coherence_index integer, volatility_index integer)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
  LANGUAGE sql                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
 AS $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
             select id, kernel_label, arc_label, coherence_index, volatility_index                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
               from quantum_kernel                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
                 order by coherence_index desc;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
                 $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
 
 CREATE OR REPLACE FUNCTION public.get_savings_profile(savings_id uuid)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
  RETURNS json                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
  LANGUAGE plpgsql                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
  SECURITY DEFINER                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
 AS $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
 declare                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
   result json;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
   begin                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
     if not public.is_staff() then                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
         raise exception 'Not allowed';                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
           end if;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
             select json_build_object(                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +
                 'plan', row_to_json(s),                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
                     'payments', (                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
                           select coalesce(json_agg(row_to_json(p)), '[]'::json)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                 from public.payments p                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
                                       where p.payer_type = 'savings_plan'                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
                                             and p.payer_id = s.id                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
                                                 ),                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
                                                     'certificate', (                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
                                                           select row_to_json(c)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                 from public.certificates c                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
                                                                       where c.holder_type = 'savings_plan'                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
                                                                             and c.holder_id = s.id                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
                                                                                   limit 1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
                                                                                       )                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
                                                                                         )                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
                                                                                           into result                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +
                                                                                             from public.savings_plans s                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
                                                                                               where s.id = savings_id;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                                                 return result;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
                                                                                                 end;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
                                                                                                 $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
 
 CREATE OR REPLACE FUNCTION public.get_temporal_probability_lattice()                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
  RETURNS TABLE(id bigint, lattice_label text, horizon_label text, probability_index integer, stability_index integer, arc_label text)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +
  LANGUAGE sql                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
 AS $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
                                select id, lattice_label, horizon_label, probability_index, stability_index, arc_label                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +
                                  from temporal_probability_lattice                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
                                    order by probability_index desc;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +
                                    $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
 
 CREATE OR REPLACE FUNCTION public.get_user_permissions()                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
  RETURNS json                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
  LANGUAGE plpgsql                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
  SECURITY DEFINER                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
 AS $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
 DECLARE                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
   me uuid := ats_current_member_id();                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +
   BEGIN                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
     RETURN (                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
         SELECT json_agg(perm.slug)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
             FROM ats_role_bindings rb                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +
                 JOIN ats_role_permissions rp ON rp.role_id = rb.role_id                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
                     JOIN ats_permissions perm ON perm.id = rp.permission_id                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
                         WHERE rb.member_id = me                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                               AND (rb.expires_at IS NULL OR rb.expires_at > now())                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
                                 );                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
                                 END;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
                                 $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
 
 CREATE OR REPLACE FUNCTION public.get_user_roles()                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
  RETURNS json                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
  LANGUAGE plpgsql                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
  SECURITY DEFINER                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
 AS $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
 DECLARE                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
   me uuid := ats_current_member_id();                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +
   BEGIN                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
     RETURN (                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
         SELECT json_agg(                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
               json_build_object(                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
                       'role_id', rb.role_id,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
                               'role_code', r.code,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
                                       'role_name', r.name,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
                                               'ministry_id', rb.ministry_id,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
                                                       'sector_id', rb.sector_id,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
                                                               'expires_at', rb.expires_at                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
                                                                     )                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +
                                                                         )                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
                                                                             FROM ats_role_bindings rb                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +
                                                                                 JOIN ats_roles r ON r.id = rb.role_id                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +
                                                                                     WHERE rb.member_id = me                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
                                                                                           AND (rb.expires_at IS NULL OR rb.expires_at > now())                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
                                                                                             );                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
                                                                                             END;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
                                                                                             $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
 
 CREATE OR REPLACE FUNCTION public.get_workflow_timeline(p_workflow_id uuid)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
  RETURNS json                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
  LANGUAGE sql                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
  SECURITY DEFINER                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
 AS $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
                                                                                                                                                                                                                                                               SELECT json_agg(                                                                                                                                                                                                                                                                                                                                                      +
                                                                                                                                                                                                                                                                   json_build_object(                                                                                                                                                                                                                                                                                                                                                +
                                                                                                                                                                                                                                                                         'state', s.state,                                                                                                                                                                                                                                                                                                                                           +
                                                                                                                                                                                                                                                                               'actor_id', s.actor_id,                                                                                                                                                                                                                                                                                                                               +
                                                                                                                                                                                                                                                                                     'note', s.note,                                                                                                                                                                                                                                                                                                                                 +
                                                                                                                                                                                                                                                                                           'created_at', s.created_at                                                                                                                                                                                                                                                                                                                +
                                                                                                                                                                                                                                                                                               )                                                                                                                                                                                                                                                                                                                                     +
                                                                                                                                                                                                                                                                                                   ORDER BY s.created_at                                                                                                                                                                                                                                                                                                             +
                                                                                                                                                                                                                                                                                                     )                                                                                                                                                                                                                                                                                                                               +
                                                                                                                                                                                                                                                                                                       FROM ats_workflow_steps s                                                                                                                                                                                                                                                                                                     +
                                                                                                                                                                                                                                                                                                         WHERE s.workflow_id = p_workflow_id;                                                                                                                                                                                                                                                                                        +
                                                                                                                                                                                                                                                                                                         $function$                                                                                                                                                                                                                                                                                                                  +
 
 CREATE OR REPLACE FUNCTION public.golden_star_propagation()                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
  RETURNS trigger                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
  LANGUAGE plpgsql                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
 AS $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
 declare                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
   sector text := TG_TABLE_NAME;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
     entity_id uuid := NEW.id;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
       new_status text := NEW.status;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
       begin                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
         -- Log Golden Star event                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
           insert into audit_trail (                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +
               entity_type,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
                   entity_id,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
                       action,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
                           actor_role,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +
                               actor_id,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
                                   commentary                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
                                     ) values (                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
                                         sector,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                             entity_id,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
                                                 'status_update',                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
                                                     current_setting('request.jwt.claims', true)::json->>'role',                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                         current_setting('request.jwt.claims', true)::json->>'sub',                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
                                                             format('Golden Star propagation: %s → %s', sector, new_status)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
                                                               );                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                 -- Update legitimacy influence                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
                                                                   update legitimacy_influence                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
                                                                     set score = score + 1,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
                                                                           updated_at = now()                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
                                                                             where entity_type = sector                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
                                                                               and entity_id = entity_id;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                                 -- Update legitimacy trust                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
                                                                                   update legitimacy_trust                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
                                                                                     set trust = trust + 1,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
                                                                                           updated_at = now()                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
                                                                                             where entity_type = sector                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
                                                                                               and entity_id = entity_id;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                                                 -- Insert anomaly detection event                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
                                                                                                   insert into legitimacy_anomalies (                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
                                                                                                       entity_type,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
                                                                                                           entity_id,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
                                                                                                               anomaly_type,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
                                                                                                                   created_at                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
                                                                                                                     ) values (                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
                                                                                                                         sector,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                                                                             entity_id,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
                                                                                                                                 'status_change',                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
                                                                                                                                     now()                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
                                                                                                                                       );                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                                                                                         -- Golden Star completion check                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
                                                                                                                                           if new_status = 'approved' then                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
                                                                                                                                               update golden_star_completion                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
                                                                                                                                                   set approved_count = approved_count + 1,                                                                                                                                                                                                                                                                                                                                                                                                                                          +
                                                                                                                                                           updated_at = now()                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
                                                                                                                                                               where sector = sector;                                                                                                                                                                                                                                                                                                                                                                                                                                                +
                                                                                                                                                                 end if;                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                                                                                                                   return NEW;                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
                                                                                                                                                                   end $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
 
 CREATE OR REPLACE FUNCTION public.handle_certificate_issue()                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
  RETURNS trigger                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
  LANGUAGE plpgsql                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
 AS $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
 begin                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +
   -- Notify your backend (via webhook or Supabase function)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
     perform pg_notify('certificate_channel', row_to_json(new)::text);                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +
       return new;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
       end;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
       $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
 
 CREATE OR REPLACE FUNCTION public.hierarchical_cte_query(p_sector_name text, p_metric_name text, p_start_date date, p_end_date date, p_institution_id uuid, p_limit integer DEFAULT 20, p_offset integer DEFAULT 0)                                                                                                                                                                                                                                                                                                                                                                                                                 +
  RETURNS TABLE(id uuid, member_id uuid, blessing text, branch text, created_at timestamp without time zone)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
  LANGUAGE plpgsql                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
 AS $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
                           BEGIN                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                             RETURN QUERY                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
                               SELECT ll.id, ll.member_id, ll.blessing, ll.branch, ll.created_at                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                 FROM lineage_logs ll                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
                                   WHERE ll.created_at BETWEEN p_start_date AND p_end_date                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
                                       AND (p_sector_name IS NULL OR ll.branch = p_sector_name)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
                                         ORDER BY ll.created_at DESC                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +
                                           LIMIT p_limit OFFSET p_offset;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
                                           END;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
                                           $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
 
 CREATE OR REPLACE FUNCTION public.hierarchical_cte_query(sector_filter text, period_filter text)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
  RETURNS TABLE(institution_id uuid, name text, sector text, metric_name text, period text, metric_value numeric)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
  LANGUAGE plpgsql                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
 AS $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
                         BEGIN                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
                           RETURN QUERY                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
                               SELECT i.institution_id,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
                                          i.name,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
                                                     i.sector,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
                                                                k.metric_name,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
                                                                           k.period,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +
                                                                                      k.metric_value                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +
                                                                                          FROM institutions i                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
                                                                                              JOIN kpis k ON k.institution_id = i.institution_id                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                                                  WHERE (sector_filter IS NULL OR LOWER(TRIM(i.sector)) ILIKE LOWER(TRIM(sector_filter)))                                                                                                                                                                                                                                                                                                                                                                                                                                            +
                                                                                                        AND (period_filter IS NULL OR LOWER(TRIM(k.period)) ILIKE LOWER(TRIM(period_filter)));                                                                                                                                                                                                                                                                                                                                                                                                                                       +
                                                                                                        END;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
                                                                                                        $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
 
 CREATE OR REPLACE FUNCTION public.increment_membership(sector text)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +
  RETURNS integer                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
  LANGUAGE plpgsql                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
  SECURITY DEFINER                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
 AS $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
 declare                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
   current_num int;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
   begin                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
     update ats_membership_numbers                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
       set counter = counter + 1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
         where sector = increment_membership.sector                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
           returning counter into current_num;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
             return current_num;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
             end;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
             $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
 
 CREATE OR REPLACE FUNCTION public.intel_multifilter(district text DEFAULT NULL::text, ministry text DEFAULT NULL::text, category text DEFAULT NULL::text)                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
  RETURNS json                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
  LANGUAGE plpgsql                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
  SECURITY DEFINER                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
 AS $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
         declare                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
           result json;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
           begin                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
             if not public.is_staff() then                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
                 raise exception 'Not allowed';                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
                   end if;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                     return (                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
                         select json_agg(row_to_json(t))                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
                             from ats_ministry_multifilter t                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
                                 where (district is null or t.district = district)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
                                       and (ministry is null or t.ministry = ministry)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +
                                             and (category is null or t.category = category)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
                                               );                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
                                               end;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
                                               $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
 
 CREATE OR REPLACE FUNCTION public.is_staff()                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
  RETURNS boolean                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
  LANGUAGE sql                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
  STABLE                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
 AS $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
   select exists (                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
       select 1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
           from public.staff                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
               where user_id = auth.uid()                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
                 );                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
                 $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
 
 CREATE OR REPLACE FUNCTION public.jwt_custom_claims(uid uuid)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
  RETURNS jsonb                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
  LANGUAGE sql                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
  SECURITY DEFINER                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
 AS $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
   select jsonb_build_object(                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
       'role',                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
             (select raw_user_meta_data ->> 'role'                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
                    from auth.users                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
                           where id = uid)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
                             );                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
                             $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
 
 CREATE OR REPLACE FUNCTION public.jwt_custom_claims(claims jsonb)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
  RETURNS jsonb                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
  LANGUAGE sql                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
  SECURITY DEFINER                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
 AS $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
   select jsonb_set(                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +
       claims,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
           '{role}',                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +
               to_jsonb(                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
                     (select raw_user_meta_data ->> 'role'                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
                            from auth.users                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
                                   where id = (claims ->> 'sub')::uuid)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
                                       ),                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
                                           true                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
                                             );                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
