  LANGUAGE sql                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
 AS $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
   select *                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
     from ledger_reconciliation_queue                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
       where status = 'pending'                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
         order by created_at asc;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
