 CREATE OR REPLACE FUNCTION public.ledger_reconciliation_report()                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
  RETURNS jsonb                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
  LANGUAGE plpgsql                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
 AS $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
 declare                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
   result jsonb;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
   begin                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
     result := jsonb_build_object(                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
         'total_entries', (select count(*) from ledger_entries),                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
             'total_issues', (select count(*) from ledger_reconciliation_issues),                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
                 'modules_checked', (select count(distinct module_name) from ledger_reconciliation_status),                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                     'module_status', (                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
                           select coalesce(                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
                                   jsonb_agg(                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
                                             jsonb_build_object(                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                         'module_name', module_name,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +
                                                                     'status', status                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
                                                                               )                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                                       ),                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
                                                                                               '[]'::jsonb                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
                                                                                                     )                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +
                                                                                                           from ledger_reconciliation_status                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
                                                                                                               ),                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                                                                   'issues', (                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
                                                                                                                         select coalesce(                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
                                                                                                                                 jsonb_agg(                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
                                                                                                                                           jsonb_build_object(                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
                                                                                                                                                       'issue_type', issue_type,                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                                                                                                                   'description', description,                                                                                                                                                                                                                                                                                                                                                                                                                                       +
                                                                                                                                                                               'related_id', related_id,                                                                                                                                                                                                                                                                                                                                                                                                                             +
                                                                                                                                                                                           'module', module                                                                                                                                                                                                                                                                                                                                                                                                                          +
                                                                                                                                                                                                     )                                                                                                                                                                                                                                                                                                                                                                                                                               +
                                                                                                                                                                                                             ),                                                                                                                                                                                                                                                                                                                                                                                                                      +
                                                                                                                                                                                                                     '[]'::jsonb                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                                                                                                                                                                           )                                                                                                                                                                                                                                                                                                                                                                                                         +
                                                                                                                                                                                                                                 from ledger_reconciliation_issues                                                                                                                                                                                                                                                                                                                                                                   +
                                                                                                                                                                                                                                     )                                                                                                                                                                                                                                                                                                                                                                                               +
                                                                                                                                                                                                                                       );                                                                                                                                                                                                                                                                                                                                                                                            +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                                                                                                                                                                                         return result;                                                                                                                                                                                                                                                                                                                                                                              +
                                                                                                                                                                                                                                         end;                                                                                                                                                                                                                                                                                                                                                                                        +
