             select                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
                 gp.id,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
                     gp.glyph_id,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
