                                     join glyphs g on g.id = gp.glyph_id                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
                                       order by gp.created_at desc;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
