 CREATE OR REPLACE FUNCTION public.list_procurement_records()                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
  RETURNS jsonb                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
  LANGUAGE sql                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
  SECURITY DEFINER                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
 AS $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
 select jsonb_agg(record)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
 from (                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
   --------------------------------------------------------------------                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
     -- EXPORT PROCUREMENT                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
       --------------------------------------------------------------------                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
         select jsonb_build_object(                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
             'record_type', 'export',                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
                 'id', e.id,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
                     'title', e.product,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
                         'intake_kg', e.volume_tons,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +
                             'revenue', e.revenue,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
                                 'status', e.status,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +
                                     'created_at', e.updated_at,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                         'community_name', c.name,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
                                             'coordinator_name', sc.name,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
                                                 'farmer_name', sf.name,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
                                                     'institution_name', i.name                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
                                                       ) as record                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
                                                         from export_intelligence e                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
                                                           left join communities c                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
                                                               on c.id = e.community_id                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
                                                                 left join stakeholders sc                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
                                                                     on sc.id = e.coordinator_id                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                       left join stakeholders sf                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                           on sf.id = e.farmer_id                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
                                                                             left join institutions i                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
                                                                                 on i.id = e.institution_id                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                                   union all                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                                     --------------------------------------------------------------------                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
                                                                                       -- AGRICULTURE PROCUREMENT                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
                                                                                         --------------------------------------------------------------------                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
                                                                                           select jsonb_build_object(                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
                                                                                               'record_type', 'agriculture',                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
                                                                                                   'id', a.id,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
                                                                                                       'title', a.crop_type,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
                                                                                                           'intake_kg', a.yield_tonnage,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
                                                                                                               'status', 'completed',                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
                                                                                                                   'created_at', a.updated_at,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
                                                                                                                       'community_name', a.community_name                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
                                                                                                                         )                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
                                                                                                                           from agriculture_production a                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                                                                             union all                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                                                                               --------------------------------------------------------------------                                                                                                                                                                                                                                                                                                                                                                                                                                  +
                                                                                                                                 -- COMMUNITY HOUSING PROCUREMENT                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
                                                                                                                                   --------------------------------------------------------------------                                                                                                                                                                                                                                                                                                                                                                                                                              +
                                                                                                                                     select jsonb_build_object(                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
                                                                                                                                         'record_type', 'community',                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +
                                                                                                                                             'id', cm.id,                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
                                                                                                                                                 'title', cm.name,                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
                                                                                                                                                     'intake_kg', cm.household_size,                                                                                                                                                                                                                                                                                                                                                                                                                                                 +
                                                                                                                                                         'status', cm.status,                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
                                                                                                                                                             'created_at', cm.created_at,                                                                                                                                                                                                                                                                                                                                                                                                                                            +
                                                                                                                                                                 'community_name', c.name                                                                                                                                                                                                                                                                                                                                                                                                                                            +
                                                                                                                                                                   )                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +
                                                                                                                                                                     from community_members cm                                                                                                                                                                                                                                                                                                                                                                                                                                       +
                                                                                                                                                                       left join communities c                                                                                                                                                                                                                                                                                                                                                                                                                                       +
                                                                                                                                                                           on c.id = cm.community_id                                                                                                                                                                                                                                                                                                                                                                                                                                 +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                                                                                                                             union all                                                                                                                                                                                                                                                                                                                                                                                                                                               +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                                                                                                                               --------------------------------------------------------------------                                                                                                                                                                                                                                                                                                                                                                                  +
                                                                                                                                                                                 -- MINING PROCUREMENT                                                                                                                                                                                                                                                                                                                                                                                                                               +
                                                                                                                                                                                   --------------------------------------------------------------------                                                                                                                                                                                                                                                                                                                                                                              +
                                                                                                                                                                                     select jsonb_build_object(                                                                                                                                                                                                                                                                                                                                                                                                                      +
                                                                                                                                                                                         'record_type', 'mining',                                                                                                                                                                                                                                                                                                                                                                                                                    +
                                                                                                                                                                                             'id', s.id,                                                                                                                                                                                                                                                                                                                                                                                                                             +
                                                                                                                                                                                                 'title', s.name,                                                                                                                                                                                                                                                                                                                                                                                                                    +
                                                                                                                                                                                                     'intake_kg', s.mechanisation_count,                                                                                                                                                                                                                                                                                                                                                                                             +
                                                                                                                                                                                                         'status', s.role,                                                                                                                                                                                                                                                                                                                                                                                                           +
                                                                                                                                                                                                             'created_at', s.created_at,                                                                                                                                                                                                                                                                                                                                                                                             +
                                                                                                                                                                                                                 'community_name', null,                                                                                                                                                                                                                                                                                                                                                                                             +
                                                                                                                                                                                                                     'institution_id', s.institution_id                                                                                                                                                                                                                                                                                                                                                                              +
                                                                                                                                                                                                                       )                                                                                                                                                                                                                                                                                                                                                                                                             +
                                                                                                                                                                                                                         from stakeholders s                                                                                                                                                                                                                                                                                                                                                                                         +
                                                                                                                                                                                                                           where s.sector = 'Mining'                                                                                                                                                                                                                                                                                                                                                                                 +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                                                                                                                                                                             union all                                                                                                                                                                                                                                                                                                                                                                                               +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                                                                                                                                                                               --------------------------------------------------------------------                                                                                                                                                                                                                                                                                                                                  +
                                                                                                                                                                                                                                 -- INSURANCE PROCUREMENT                                                                                                                                                                                                                                                                                                                                                                            +
                                                                                                                                                                                                                                   --------------------------------------------------------------------                                                                                                                                                                                                                                                                                                                              +
                                                                                                                                                                                                                                     select jsonb_build_object(                                                                                                                                                                                                                                                                                                                                                                      +
                                                                                                                                                                                                                                         'record_type', 'insurance',                                                                                                                                                                                                                                                                                                                                                                 +
                                                                                                                                                                                                                                             'id', s.id,                                                                                                                                                                                                                                                                                                                                                                             +
                                                                                                                                                                                                                                                 'title', s.name,                                                                                                                                                                                                                                                                                                                                                                    +
                                                                                                                                                                                                                                                     'intake_kg', s.legitimacy_score,                                                                                                                                                                                                                                                                                                                                                +
                                                                                                                                                                                                                                                         'status', s.role,                                                                                                                                                                                                                                                                                                                                                           +
                                                                                                                                                                                                                                                             'created_at', s.created_at,                                                                                                                                                                                                                                                                                                                                             +
                                                                                                                                                                                                                                                                 'community_name', null,                                                                                                                                                                                                                                                                                                                                             +
                                                                                                                                                                                                                                                                     'institution_id', s.institution_id                                                                                                                                                                                                                                                                                                                              +
                                                                                                                                                                                                                                                                       )                                                                                                                                                                                                                                                                                                                                                             +
                                                                                                                                                                                                                                                                         from stakeholders s                                                                                                                                                                                                                                                                                                                                         +
                                                                                                                                                                                                                                                                           where s.sector = 'Insurance'                                                                                                                                                                                                                                                                                                                              +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                                                                                                                                                                                                                           ) t;                                                                                                                                                                                                                                                                                                                                                      +
                                                                                                                                                                                                                                                                           $function$                                                                                                                                                                                                                                                                                                                                                +
 
 CREATE OR REPLACE FUNCTION public.list_stakeholder_pdfs(p_stakeholder_id uuid)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
  RETURNS TABLE(id uuid, glyph_title text, pdf_url text, created_at timestamp with time zone)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
  LANGUAGE sql                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
 AS $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
           select gp.id, g.title, gp.pdf_url, gp.created_at                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
             from glyph_pdfs gp                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
               join glyphs g on g.id = gp.glyph_id                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
                 where gp.stakeholder_id = p_stakeholder_id                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
                   order by gp.created_at asc;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
                   $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
 
 CREATE OR REPLACE FUNCTION public.list_tax_reprieve_pdfs()                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
  RETURNS TABLE(id uuid, glyph_id uuid, pdf_url text, ministries text[], tags text[], created_at timestamp with time zone)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
  LANGUAGE sql                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
 AS $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
               select id, glyph_id, pdf_url, ministries, tags, created_at                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
                 from glyph_pdfs                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                   where 'tax_reprieve' = any(tags)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
                     order by created_at desc;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
                     $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
 
 CREATE OR REPLACE FUNCTION public.log_entity_action()                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +
  RETURNS trigger                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
  LANGUAGE plpgsql                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
 AS $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
 DECLARE                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
   entity TEXT;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
     stakeholder_name TEXT;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
     BEGIN                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
       -- Determine entity type                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
         IF TG_TABLE_NAME = 'proposals' THEN                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
             entity := 'Proposal';                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
               ELSIF TG_TABLE_NAME = 'housing_kpis' THEN                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
                   entity := 'Housing KPI';                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
                     ELSIF TG_TABLE_NAME = 'mining_kpis' THEN                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
                         entity := 'Mining KPI';                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                           ELSIF TG_TABLE_NAME = 'financing' THEN                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
                               entity := 'Financing';                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
                                 ELSE                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
                                     entity := 'Unknown';                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
                                       END IF;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                         -- Derive stakeholder name from JWT role                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
                                           stakeholder_name := current_setting('request.jwt.claims', true)::json->>'role';                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                             -- Insert into audit trail                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
                                               INSERT INTO audit_trail(entity_type, entity_id, action, actor_role, actor_id, stakeholder, comment, timestamp)                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
                                                 VALUES (                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
                                                     entity,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
                                                         NEW.id,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                             TG_OP,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
                                                                 current_setting('request.jwt.claims', true)::json->>'role',                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
                                                                     (current_setting('request.jwt.claims', true)::json->>'sub')::uuid,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
                                                                         stakeholder_name,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
                                                                             entity || ' action logged',                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
                                                                                 now()                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +
                                                                                   );                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                                     RETURN NEW;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                                     END;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
                                                                                     $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
 
 CREATE OR REPLACE FUNCTION public.log_financing_action()                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
  RETURNS trigger                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
