 CREATE OR REPLACE FUNCTION public.procurement_geojson()                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
  RETURNS jsonb                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
  LANGUAGE sql                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
 AS $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
 with recs as (                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
   select                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
       r->>'community_name' as community_name,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
           (r->>'intake_kg')::numeric as intake_kg                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
             from jsonb_array_elements(list_procurement_records()) r                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +
             ),                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
             agg as (                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
               select                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
                   community_name,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
                       sum(intake_kg) as total_intake                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
                         from recs                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
                           group by community_name                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
                           )                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
                           select jsonb_build_object(                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
                             'type', 'FeatureCollection',                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
                               'features', jsonb_agg(                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
                                   jsonb_build_object(                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +
                                         'type', 'Feature',                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
                                               'geometry', c.location,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +
                                                     'properties', jsonb_build_object(                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +
                                                             'community', c.name,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
                                                                     'intake_kg', coalesce(a.total_intake, 0)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
                                                                           )                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
                                                                               )                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                                 )                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
                                                                                 )                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
                                                                                 from communities c                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
                                                                                 left join agg a                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                                   on a.community_name = c.name;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                                   $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
 
 CREATE OR REPLACE FUNCTION public.recalc_federation_sync()                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
  RETURNS void                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
  LANGUAGE sql                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
 AS $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
 update federation_nodes                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
 set                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +
   is_in_sync = sync_level >= 70,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
     last_sync_at = coalesce(last_sync_at, now());                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
     $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
 
