 AS $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
     begin                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
       update ledger_reconciliation_queue                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
         set status = 'resolved',                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
               resolved_at = now()                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
                 where id = reconciliation_id;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                   insert into ledger_reconciliation_log (reconciliation_id, resolved_at)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
                     values (reconciliation_id, now())                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +
                       on conflict do nothing;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
