 CREATE OR REPLACE FUNCTION public.rls_auto_enable()                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +
  RETURNS event_trigger                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
  LANGUAGE plpgsql                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
  SET search_path TO 'pg_catalog'                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
 AS $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
 DECLARE                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
   cmd record;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
   BEGIN                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
     FOR cmd IN                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
         SELECT *                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
             FROM pg_event_trigger_ddl_commands()                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
                 WHERE command_tag IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
                       AND object_type IN ('table','partitioned table')                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
                         LOOP                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
                              IF cmd.schema_name IS NOT NULL                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
                                      AND cmd.schema_name IN ('public')                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
                                              AND cmd.schema_name NOT IN ('pg_catalog','information_schema')                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
                                                      AND cmd.schema_name NOT LIKE 'pg_toast%'                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
                                                              AND cmd.schema_name NOT LIKE 'pg_temp%' THEN                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
                                                                    BEGIN                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
                                                                            EXECUTE format('alter table if exists %s enable row level security', cmd.object_identity);                                                                                                                                                                                                                                                                                                                                                                                                                                                               +
                                                                                    RAISE LOG 'rls_auto_enable: enabled RLS on %', cmd.object_identity;                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
                                                                                          EXCEPTION                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
                                                                                                  WHEN OTHERS THEN                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
                                                                                                            RAISE LOG 'rls_auto_enable: failed to enable RLS on %', cmd.object_identity;                                                                                                                                                                                                                                                                                                                                                                                                                                             +
                                                                                                                  END;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +
                                                                                                                       ELSE                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
                                                                                                                               RAISE LOG 'rls_auto_enable: skip % (either system schema or not in enforced list: %.)',                                                                                                                                                                                                                                                                                                                                                                                                               +
                                                                                                                                                 cmd.object_identity, cmd.schema_name;                                                                                                                                                                                                                                                                                                                                                                                                                                               +
                                                                                                                                                      END IF;                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
                                                                                                                                                        END LOOP;                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
                                                                                                                                                        END;                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
                                                                                                                                                        $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
 
 CREATE OR REPLACE FUNCTION public.run_legitimacy_flow()                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
  RETURNS void                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
  LANGUAGE plpgsql                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
  SECURITY DEFINER                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
 AS $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
 BEGIN                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +
   -- Step 1: Normalize audit trail rows                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
     UPDATE audit_trail                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
       SET action = 'comment'                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
         WHERE action NOT IN ('affirm','reject','comment');                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
           -- Step 2: Drop and recreate constraint                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
             ALTER TABLE audit_trail DROP CONSTRAINT IF EXISTS audit_trail_action_check;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
               ALTER TABLE audit_trail ADD CONSTRAINT audit_trail_action_check                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
                   CHECK (action IN (                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
                         'affirm',                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
                               'reject',                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
                                     'comment',                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
                                           'Reviewed KPI submission',                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
                                                 'Requested financial projection',                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
                                                       'Rejected pricing model'                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
                                                           ));                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                             -- Step 3: Seed KPIs                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
                                                               INSERT INTO kpis (institution_id, metric_name, metric_value) VALUES                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
                                                                   ('9dcdea8e-a60e-4bf0-a089-fa7e9be698b1', 'Total Assets', 1200000000),                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
                                                                       ('9dcdea8e-a60e-4bf0-a089-fa7e9be698b1', 'Net Profit', 45000000),                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
                                                                           ('6432116b-e80f-4f75-9578-ddc34f949766', 'Subscribers', 12000000),                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
                                                                               ('6432116b-e80f-4f75-9578-ddc34f949766', 'Loans Disbursed', 750000),                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
                                                                                   ('d33a05d1-eb54-45f9-aa64-35be7ae96641', 'Policies Issued', 500000),                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
                                                                                       ('d33a05d1-eb54-45f9-aa64-35be7ae96641', 'Community Projects', 250);                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                                         -- Step 4: Seed Audit Trail linked to KPIs                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
                                                                                           INSERT INTO audit_trail (stakeholder, action, commentary, kpi_id) VALUES                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
                                                                                               ('Government Regulator', 'Reviewed KPI submission', 'All metrics verified',                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
                                                                                                    (SELECT kpi_id FROM kpis WHERE metric_name = 'Total Assets' AND institution_id = '9dcdea8e-a60e-4bf0-a089-fa7e9be698b1' LIMIT 1)),                                                                                                                                                                                                                                                                                                                                                                                               +
                                                                                                        ('Investor', 'Requested financial projection', 'Scenario-based model delivered',                                                                                                                                                                                                                                                                                                                                                                                                                                             +
                                                                                                             (SELECT kpi_id FROM kpis WHERE metric_name = 'Subscribers' AND institution_id = '6432116b-e80f-4f75-9578-ddc34f949766' LIMIT 1)),                                                                                                                                                                                                                                                                                                                                                                                       +
                                                                                                                 ('Community Board', 'Rejected pricing model', 'Concerns about affordability',                                                                                                                                                                                                                                                                                                                                                                                                                                       +
                                                                                                                      (SELECT kpi_id FROM kpis WHERE metric_name = 'Policies Issued' AND institution_id = 'd33a05d1-eb54-45f9-aa64-35be7ae96641' LIMIT 1));                                                                                                                                                                                                                                                                                                                                                                          +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                                                                        -- Step 5: Projects glyph test (Insert → Update → Delete)                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
                                                                                                                          INSERT INTO projects (title, description, aura_overlay, pdf_export_link)                                                                                                                                                                                                                                                                                                                                                                                                                                   +
                                                                                                                            VALUES ('Legitimacy Flow Pilot', 'Initial glyph test project', 'Ceremonial aura glyph', 'https://example.com/export/legitimacy-flow.pdf');                                                                                                                                                                                                                                                                                                                                                               +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                                                                              UPDATE projects                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
                                                                                                                                SET description = 'Updated glyph test project with expanded legitimacy flows',                                                                                                                                                                                                                                                                                                                                                                                                                       +
                                                                                                                                      aura_overlay = 'Ripple aura glyph',                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
                                                                                                                                            pdf_export_link = 'https://example.com/export/legitimacy-flow-v2.pdf'                                                                                                                                                                                                                                                                                                                                                                                                                    +
                                                                                                                                              WHERE title = 'Legitimacy Flow Pilot';                                                                                                                                                                                                                                                                                                                                                                                                                                                 +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                                                                                                DELETE FROM projects                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +
                                                                                                                                                  WHERE title = 'Legitimacy Flow Pilot';                                                                                                                                                                                                                                                                                                                                                                                                                                             +
                                                                                                                                                  END;                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +
                                                                                                                                                  $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
 
 CREATE OR REPLACE FUNCTION public.sanctify_legitimacy(role_name text)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +
  RETURNS void                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
  LANGUAGE plpgsql                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
  SECURITY DEFINER                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
 AS $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
 declare                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
   uid uuid := auth.uid();                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
   begin                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
     update legitimacy                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +
       set progress = 75,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
             stage = 'sanctified',                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
                   updated_at = now()                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
                     where user_id = uid                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
                         and role = role_name;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
                         end;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
                         $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
 
 CREATE OR REPLACE FUNCTION public.seed_demo_email_logs(branch_name text, demo_count integer)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
  RETURNS void                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
  LANGUAGE plpgsql                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
 AS $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
       declare                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
         i int;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
         begin                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
           for i in 1..demo_count loop                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +
               insert into email_log (name, branch, date, email, pdf_url, status, sent_at, is_demo)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
                   values (                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
                         'Demo User ' || i,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
                               branch_name,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
                                     current_date,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
                                           'demo' || i || '@example.com',                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
                                                 'https://example.com/demo' || i || '.pdf',                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
                                                       case when i % 2 = 0 then 'failed' else 'sent' end,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
                                                             now(),                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
                                                                   true                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
                                                                       );                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
                                                                         end loop;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
                                                                         end;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
