 CREATE OR REPLACE FUNCTION public.seed_seasonal_blessings()                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
  RETURNS void                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
  LANGUAGE plpgsql                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
 AS $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
 begin                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +
   insert into blessings (text) values                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +
       ('✨ Spring renewal: May our covenant blossom anew beneath the Golden Star. ✨'),                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
           ('✨ Summer strength: May our branches shine with radiant unity. ✨'),                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
               ('✨ Autumn harvest: May lineage affirm abundance and covenant trust. ✨'),                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
                   ('✨ Winter reflection: May our covenant endure, sanctified in eternal light. ✨');                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +
                   end;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
