 CREATE OR REPLACE FUNCTION public.set_branch_claim()                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
  RETURNS trigger                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
  LANGUAGE plpgsql                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
 AS $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
 BEGIN                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +
   -- Example: assign branch based on email domain                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
     IF NEW.email LIKE '%@banking.com' THEN                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
         NEW.raw_app_meta_data = jsonb_set(NEW.raw_app_meta_data, '{branch}', '"Banking"');                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
           ELSIF NEW.email LIKE '%@veterans.org' THEN                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
               NEW.raw_app_meta_data = jsonb_set(NEW.raw_app_meta_data, '{branch}', '"Veterans"');                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
                 ELSIF NEW.email LIKE '%@cement.co' THEN                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
                     NEW.raw_app_meta_data = jsonb_set(NEW.raw_app_meta_data, '{branch}', '"Cement"');                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +
                       ELSIF NEW.email LIKE '%@steel.co' THEN                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
                           NEW.raw_app_meta_data = jsonb_set(NEW.raw_app_meta_data, '{branch}', '"Steel"');                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
                             ELSE                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
                                 NEW.raw_app_meta_data = jsonb_set(NEW.raw_app_meta_data, '{branch}', '"Government"');                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +
                                   END IF;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
                                     RETURN NEW;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                     END;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
                                     $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
 
