 CREATE OR REPLACE FUNCTION public.update_blessings_count()                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
  RETURNS trigger                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
  LANGUAGE plpgsql                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
 AS $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
 BEGIN                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +
   UPDATE stakeholders                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +
     SET blessings_count = blessings_count + 1,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
           updated_at = NOW()                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
             WHERE id = NEW.stakeholder_id;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
               INSERT INTO lineage_tally (branch, total_blessings, last_updated)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                 VALUES (NEW.branch, 1, NOW())                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
                   ON CONFLICT (branch)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
                     DO UPDATE SET total_blessings = lineage_tally.total_blessings + 1,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
                                     last_updated = NOW();                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                       RETURN NEW;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
                                       END;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
