 CREATE OR REPLACE FUNCTION public.update_federation_sync(node_id uuid, new_sync_level integer)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
  RETURNS void                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
  LANGUAGE sql                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
 AS $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
       update federation_nodes                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
