 CREATE OR REPLACE FUNCTION public.update_legitimacy_on_enrol()                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
  RETURNS trigger                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
  LANGUAGE plpgsql                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
 AS $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
 begin                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +
   insert into legitimacy (user_id, role, progress, stage)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
     values (new.user_id, TG_TABLE_NAME, 25, 'initiated')                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
       on conflict (user_id, role)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
         do update set                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +
             progress = 25,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
                 stage = 'initiated',                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
                     updated_at = now();                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                       return new;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
                       end;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
