 CREATE OR REPLACE FUNCTION public.update_unit_full_status()                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
  RETURNS trigger                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
  LANGUAGE plpgsql                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
 AS $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
 begin                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +
     -- Update current families count                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
         update units                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
             set current_families = current_families + 1                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
                 where id = NEW.unit_id;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                     -- Mark unit as FULL if max reached                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
                         update units                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
                             set                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                     is_full = (current_families >= max_families),                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
                                             unit_status = case                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      +
                                                         when current_families >= max_families then 'Full'                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
                                                                     when current_families > 0 then 'Partially Allocated'                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
                                                                                 else 'Available'                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
                                                                                         end                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
                                                                                             where id = NEW.unit_id;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                                                                                                 return NEW;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         +
                                                                                                 end;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
                                                                                                 $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
 
 CREATE OR REPLACE FUNCTION public.verify_certificate(cert_id uuid)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
  RETURNS json                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
  LANGUAGE plpgsql                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
  SECURITY DEFINER                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
 AS $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
 declare                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
   cert json;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
   begin                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
     if not public.is_staff() then                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
         raise exception 'Not allowed';                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              +
           end if;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
             select row_to_json(c)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
               into cert                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
                 from public.certificates c                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
                   where c.id = cert_id;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                     if cert is null then                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
                         return json_build_object('status','not_found');                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
                           end if;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                             return json_build_object(                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +
                                 'status','valid',                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
                                     'certificate', cert                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
                                       );                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
                                       end;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          +
                                       $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    +
 
 CREATE OR REPLACE FUNCTION public.verify_legitimacy(role_name text)                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 +
  RETURNS void                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
  LANGUAGE plpgsql                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
  SECURITY DEFINER                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   +
 AS $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
 declare                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
   uid uuid := auth.uid();                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           +
   begin                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
     update legitimacy                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               +
       set progress = 50,                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            +
             stage = 'verified',                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     +
                   updated_at = now()                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                +
                     where user_id = uid                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             +
                         and role = role_name;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       +
                         end;                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        +
                         $function$                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  +
 
